INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('b9dd1772-6055-5092-a684-b89acb63bc79', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 35, 35, 'The farmers took his servants, beat one, killed another, and stoned another.'),
  ('1520158c-2e3a-5ddf-a6d5-16f44902ea43', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 36, 36, 'Again, he sent other servants more than the first: and they treated them the same way.'),
  ('c3317c48-7953-5a8b-a5a1-1c8c9e81622b', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 37, 37, 'But afterward he sent to them his son, saying, ''They will respect my son.'''),
  ('2e26a6ee-f859-53be-a21f-e0a1f5a1608e', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 38, 38, 'But the farmers, when they saw the son, said among themselves, ''This is the heir. Come, let''s kill him, and seize his inheritance.'''),
  ('33c9d3ab-44bc-588c-ac88-99d2ce1b2b09', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 39, 39, 'So they took him, and threw him out of the vineyard, and killed him.'),
  ('8224c287-4bfa-588e-abdb-d730a973bfce', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 40, 40, 'When therefore the lord of the vineyard comes, what will he do to those farmers?"'),
  ('cdc95bd6-e242-586e-a7e3-163c507c5186', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 41, 41, 'They told him, "He will miserably destroy those miserable men, and will lease out the vineyard to other farmers, who will give him the fruit in its season."'),
  ('f8dbc935-b2d5-597f-a864-a1e22fff2f09', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 42, 42, 'Jesus said to them, "Did you never read in the Scriptures, ''The stone which the builders rejected, the same was made the head of the corner. This was from the Lord. It is marvelous in our eyes?'''),
  ('5c232011-c412-51d7-afd4-c13ad0a7cb81', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 43, 43, '"Therefore I tell you, the Kingdom of God will be taken away from you, and will be given to a nation bringing forth its fruit.'),
  ('3f52beea-9ac2-5f26-a66f-84c88fce9cb2', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 44, 44, 'He who falls on this stone will be broken to pieces, but on whoever it will fall, it will scatter him as dust."'),
  ('8cc179fa-d140-5076-a00e-dcc238378e4f', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 45, 45, 'When the chief priests and the Pharisees heard his parables, they perceived that he spoke about them.'),
  ('5381b8fe-a694-59a2-aef8-8c631bed7d3f', 'f9711c8a-4128-5782-af25-a32eff720adb', NULL, 46, 46, 'When they sought to seize him, they feared the multitudes, because they considered him to be a prophet.'),
  ('9a3d03e2-4b23-5dc2-a95f-720a5c1672cc', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 1, 1, 'Jesus answered and spoke again in parables to them, saying,'),
  ('b2af9f39-0469-5bb5-a7d1-09ad98cac358', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 2, 2, '"The Kingdom of Heaven is like a certain king, who made a marriage feast for his son,'),
  ('bcee7878-a577-52ad-a60c-e2006f41cbec', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 3, 3, 'and sent out his servants to call those who were invited to the marriage feast, but they would not come.'),
  ('3c8070f7-df4e-557b-a428-e3c87a0c20bd', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 4, 4, 'Again he sent out other servants, saying, ''Tell those who are invited, "Behold, I have prepared my dinner. My cattle and my fatlings are killed, and all things are ready. Come to the marriage feast!"'''),
  ('bd06387a-695b-5e42-a2c5-2141bd108b23', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 5, 5, 'But they made light of it, and went their ways, one to his own farm, another to his merchandise,'),
  ('a59dbaf8-9a26-57e7-ae1f-824d840058ba', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 6, 6, 'and the rest grabbed his servants, and treated them shamefully, and killed them.'),
  ('7e1ee04b-6a5c-59ec-ace7-9d6502b66e02', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 7, 7, 'When the king heard that, he was angry, and sent his armies, destroyed those murderers, and burned their city.'),
  ('fc09b09d-9ed3-5863-a3b2-6d95de3b2377', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 8, 8, '"Then he said to his servants, ''The wedding is ready, but those who were invited weren''t worthy.'),
  ('373d7913-9f3a-5b89-ae1c-c3bf7e1e6c46', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 9, 9, 'Go therefore to the intersections of the highways, and as many as you may find, invite to the marriage feast.'''),
  ('cec0436b-0b78-5916-a6e9-2461d5dc3c0b', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 10, 10, 'Those servants went out into the highways, and gathered together as many as they found, both bad and good. The wedding was filled with guests.'),
  ('62e48c6b-ff95-5584-aff1-f5dd0f9a4c8c', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 11, 11, 'But when the king came in to see the guests, he saw there a man who didn''t have on wedding clothing,'),
  ('5c36dc00-e0d1-558b-afb3-124561e8f4bc', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 12, 12, 'and he said to him, ''Friend, how did you come in here not wearing wedding clothing?'' He was speechless.'),
  ('56cfd7c6-e3f4-5308-a596-f6b3e6b37767', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 13, 13, 'Then the king said to the servants, ''Bind him hand and foot, take him away, and throw him into the outer darkness; there is where the weeping and grinding of teeth will be.'''),
  ('c464b20f-6807-5494-a6a1-ea27a17d5ed3', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 14, 14, 'For many are called, but few chosen."'),
  ('412f7687-a9bc-50ce-af3a-53fbaec909b1', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 15, 15, 'Then the Pharisees went and took counsel how they might entrap him in his talk.'),
  ('1c108411-f319-53b2-ac96-f32e7d20b933', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 16, 16, 'They sent their disciples to him, along with the Herodians, saying, "Teacher, we know that you are honest, and teach the way of God in truth, no matter who you teach, for you aren''t partial to anyone.'),
  ('7e2b3b62-ae08-5336-ae14-ad1ad9ed1642', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 17, 17, 'Tell us therefore, what do you think? Is it lawful to pay taxes to Caesar, or not?"'),
  ('1e8b542c-8572-5962-ad80-0a439d0d8376', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 18, 18, 'But Jesus perceived their wickedness, and said, "Why do you test me, you hypocrites?'),
  ('df5f17fc-d1ec-54d0-a69e-8807db98e388', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 19, 19, 'Show me the tax money." They brought to him a denarius.'),
  ('64831200-1311-5e57-a6f2-8e87453a91f7', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 20, 20, 'He asked them, "Whose is this image and inscription?"'),
  ('c4363254-1883-544e-a89e-92458e3bed7a', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 21, 21, 'They said to him, "Caesar''s." Then he said to them, "Give therefore to Caesar the things that are Caesar''s, and to God the things that are God''s."'),
  ('d1050296-647c-5e8a-a92f-72b2ca32b815', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 22, 22, 'When they heard it, they marveled, and left him, and went away.'),
  ('c007be03-62de-517d-a7a6-ff522766559a', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 23, 23, 'On that day Sadducees (those who say that there is no resurrection) came to him. They asked him,'),
  ('ee7abba1-26ab-555e-a048-e425291deea9', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 24, 24, 'saying, "Teacher, Moses said, ''If a man dies, having no children, his brother shall marry his wife, and raise up seed for his brother.'''),
  ('2f7a82f6-3d9f-51eb-a18d-5513337d7bd2', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 25, 25, 'Now there were with us seven brothers. The first married and died, and having no seed left his wife to his brother.'),
  ('72611bbb-1a9d-5d3c-ac8c-a8ca284269d7', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 26, 26, 'In the same way, the second also, and the third, to the seventh.'),
  ('55ad0af5-eb8c-5be1-a451-65b181d3ee49', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 27, 27, 'After them all, the woman died.'),
  ('d8dcbc14-5ec3-563b-a2d4-4a9e2e1b7f7b', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 28, 28, 'In the resurrection therefore, whose wife will she be of the seven? For they all had her."'),
  ('244111ab-3821-58f7-ab35-edee834b4b3b', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 29, 29, 'But Jesus answered them, "You are mistaken, not knowing the Scriptures, nor the power of God.'),
  ('4b31eb3d-48ea-5026-ae08-dc1480e74111', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 30, 30, 'For in the resurrection they neither marry, nor are given in marriage, but are like God''s angels in heaven.'),
  ('dda32a69-c421-572a-a386-1e8aff290264', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 31, 31, 'But concerning the resurrection of the dead, haven''t you read that which was spoken to you by God, saying,'),
  ('473d00e2-c274-525f-aa46-732a71c57d03', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 32, 32, '''I am the God of Abraham, and the God of Isaac, and the God of Jacob?'' God is not the God of the dead, but of the living."'),
  ('dc69f029-5eeb-56df-af53-bdde6e34e12e', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 33, 33, 'When the multitudes heard it, they were astonished at his teaching.'),
  ('c10b24d1-dc38-5e15-aa7c-d71079f0a738', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 34, 34, 'But the Pharisees, when they heard that he had silenced the Sadducees, gathered themselves together.'),
  ('149fdaac-ad75-52f7-a969-d5fd287eddad', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 35, 35, 'One of them, a lawyer, asked him a question, testing him.'),
  ('8612b3fc-03c3-5514-a1f5-06a77598a525', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 36, 36, '"Teacher, which is the greatest commandment in the law?"'),
  ('4e6d4073-fc6f-5602-a820-ef1792bbfb6b', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 37, 37, 'Jesus said to him, "''You shall love the Lord your God with all your heart, with all your soul, and with all your mind.'''),
  ('723ab853-b992-5cc2-a406-e6e6babb2abc', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 38, 38, 'This is the first and great commandment.'),
  ('1367604a-18a5-524c-a029-2fed2150dc60', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 39, 39, 'A second likewise is this, ''You shall love your neighbor as yourself.'''),
  ('3889a6c9-bab5-51a0-aef2-18219a3d3de6', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 40, 40, 'The whole law and the prophets depend on these two commandments."'),
  ('eb7b251f-0d6b-5dbf-a39b-83c27dbcf8ff', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 41, 41, 'Now while the Pharisees were gathered together, Jesus asked them a question,'),
  ('82c11a43-d66b-5f11-af31-f7fd3a42483f', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 42, 42, 'saying, "What do you think of the Christ? Whose son is he?" They said to him, "Of David."'),
  ('04a97001-23dd-5ea7-a8af-c9c0857fc965', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 43, 43, 'He said to them, "How then does David in the Spirit call him Lord, saying,'),
  ('ad010f06-0a65-55be-a0f0-992d7656725e', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 44, 44, '''The Lord said to my Lord, sit on my right hand, until I make your enemies a footstool for your feet?'''),
  ('64190659-9ce2-5991-a10f-b1db64afd9d0', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 45, 45, '"If then David calls him Lord, how is he his son?"'),
  ('a553dcda-8a05-55d3-a3d5-80bb4cb82887', 'f462aee7-11e6-5946-af64-152519f61c06', NULL, 46, 46, 'No one was able to answer him a word, neither did any man dare ask him any more questions from that day forth.'),
  ('0b8792fc-118b-5b34-a7a6-93afba830b81', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 1, 1, 'Then Jesus spoke to the multitudes and to his disciples,'),
  ('e3d2c41f-c23b-53eb-a313-56b0a79045bc', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 2, 2, 'saying, "The scribes and the Pharisees sat on Moses'' seat.'),
  ('9f67fde7-91c1-52ed-a17a-6b4c8250f76c', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 3, 3, 'All things therefore whatever they tell you to observe, observe and do, but don''t do their works; for they say, and don''t do.'),
  ('cbfc32b3-5f9f-5210-aa0e-b36d94977a83', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 4, 4, 'For they bind heavy burdens that are grievous to be borne, and lay them on men''s shoulders; but they themselves will not lift a finger to help them.'),
  ('a71edc9d-670f-51e3-a70a-89f98afeb3f0', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 5, 5, 'But all their works they do to be seen by men. They make their phylacteries broad, enlarge the fringes of their garments,'),
  ('16c58774-8597-5139-a232-c13eda6b96c2', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 6, 6, 'and love the place of honor at feasts, the best seats in the synagogues,'),
  ('f98c1364-837e-527e-ad47-232414debe80', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 7, 7, 'the salutations in the marketplaces, and to be called ''Rabbi, Rabbi'' by men.'),
  ('6f1edfa6-3625-58ff-a74e-6b965e1b291a', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 8, 8, 'But don''t you be called ''Rabbi,'' for one is your teacher, the Christ, and all of you are brothers.'),
  ('e48ba5e3-5364-59dd-a0a7-e8ad7efacd46', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 9, 9, 'Call no man on the earth your father, for one is your Father, he who is in heaven.'),
  ('bcc4ceec-88aa-58af-a28d-98ea5bb49f73', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 10, 10, 'Neither be called masters, for one is your master, the Christ.'),
  ('0f04eabb-4bf0-5313-aeeb-eccd8cec5249', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 11, 11, 'But he who is greatest among you will be your servant.'),
  ('5f83be71-a3b6-5185-a9c7-ae38b7fb0954', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 12, 12, 'Whoever exalts himself will be humbled, and whoever humbles himself will be exalted.'),
  ('0ad56cca-3872-5b9a-aeef-0a886dc880d7', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 13, 13, '"Woe to you, scribes and Pharisees, hypocrites! For you devour widows'' houses, and as a pretense you make long prayers. Therefore you will receive greater condemnation.'),
  ('fccb5ce2-7f80-53a6-a0d3-e00b0bde436b', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 14, 14, '"But woe to you, scribes and Pharisees, hypocrites! Because you shut up the Kingdom of Heaven against men; for you don''t enter in yourselves, neither do you allow those who are entering in to enter.'),
  ('cc791d7f-0401-5d86-a784-ad3d50983211', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 15, 15, 'Woe to you, scribes and Pharisees, hypocrites! For you travel around by sea and land to make one proselyte; and when he becomes one, you make him twice as much of a son of Gehenna as yourselves.'),
  ('4d488001-d0eb-57be-acac-879fb85a0a9a', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 16, 16, '"Woe to you, you blind guides, who say, ''Whoever swears by the temple, it is nothing; but whoever swears by the gold of the temple, he is obligated.'''),
  ('14c5537d-afad-5143-a4e6-d145159579de', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 17, 17, 'You blind fools! For which is greater, the gold, or the temple that sanctifies the gold?'),
  ('947d2413-77c5-5733-ae85-cdd9f69db01c', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 18, 18, '''Whoever swears by the altar, it is nothing; but whoever swears by the gift that is on it, he is obligated?'''),
  ('31d3d205-966a-557f-aee3-90fc19ca24b6', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 19, 19, 'You blind fools! For which is greater, the gift, or the altar that sanctifies the gift?'),
  ('734af260-50d0-57a2-a3f8-1b533b945657', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 20, 20, 'He therefore who swears by the altar, swears by it, and by everything on it.'),
  ('43d8fcdd-1829-545c-a2cb-552a27b744fe', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 21, 21, 'He who swears by the temple, swears by it, and by him who was living in it.'),
  ('cb2fa8e3-fb32-5ba8-a652-d3d5b5877d11', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 22, 22, 'He who swears by heaven, swears by the throne of God, and by him who sits on it.'),
  ('0d2e0ed0-9354-509e-a27c-d10b2f39a924', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 23, 23, '"Woe to you, scribes and Pharisees, hypocrites! For you tithe mint, dill, and cumin, and have left undone the weightier matters of the law: justice, mercy, and faith. But you ought to have done these, and not to have left the other undone.'),
  ('907635db-3ca2-59ab-a22a-8933f7dfa357', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 24, 24, 'You blind guides, who strain out a gnat, and swallow a camel!'),
  ('180eaafb-98cc-5dad-aa7c-123bbaa399e9', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 25, 25, '"Woe to you, scribes and Pharisees, hypocrites! For you clean the outside of the cup and of the platter, but within they are full of extortion and unrighteousness.'),
  ('f9e42bb2-eda4-56b1-aecd-d2d18daab590', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 26, 26, 'You blind Pharisee, first clean the inside of the cup and of the platter, that its outside may become clean also.'),
  ('6bd38a5a-a806-5792-ac01-ca1b8425305e', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 27, 27, '"Woe to you, scribes and Pharisees, hypocrites! For you are like whitened tombs, which outwardly appear beautiful, but inwardly are full of dead men''s bones, and of all uncleanness.'),
  ('bb969e74-8be3-5383-afef-0d843a2219ad', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 28, 28, 'Even so you also outwardly appear righteous to men, but inwardly you are full of hypocrisy and iniquity.'),
  ('b0386f28-92d3-54f4-a886-71e9ee90fe14', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 29, 29, '"Woe to you, scribes and Pharisees, hypocrites! For you build the tombs of the prophets, and decorate the tombs of the righteous,'),
  ('308c6c74-7012-539f-ae2f-07b2a5779376', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 30, 30, 'and say, ''If we had lived in the days of our fathers, we wouldn''t have been partakers with them in the blood of the prophets.'''),
  ('0efb53ce-8239-5d4a-a2b7-cc72722db79a', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 31, 31, 'Therefore you testify to yourselves that you are children of those who killed the prophets.'),
  ('e62a0634-b53b-5310-a515-728196e2593b', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 32, 32, 'Fill up, then, the measure of your fathers.'),
  ('9c5e9f39-3187-53f0-a26c-b7ae411bca0d', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 33, 33, 'You serpents, you offspring of vipers, how will you escape the judgment of Gehenna?'),
  ('1b1ab1a5-7360-5047-ab21-785dd5dd7f99', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 34, 34, 'Therefore, behold, I send to you prophets, wise men, and scribes. Some of them you will kill and crucify; and some of them you will scourge in your synagogues, and persecute from city to city;'),
  ('6eba6495-b8cf-56e5-a8c6-95de29186875', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 35, 35, 'that on you may come all the righteous blood shed on the earth, from the blood of righteous Abel to the blood of Zachariah son of Barachiah, whom you killed between the sanctuary and the altar.'),
  ('284cee1a-ecc9-57b0-aa8c-b39ce773e0f9', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 36, 36, 'Most certainly I tell you, all these things will come upon this generation.'),
  ('62ee8941-b8a7-527e-a5e3-7d3711bcc42b', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 37, 37, '"Jerusalem, Jerusalem, who kills the prophets, and stones those who are sent to her! How often I would have gathered your children together, even as a hen gathers her chicks under her wings, and you would not!'),
  ('2e5e76f7-aa90-5e3f-a084-907c479d41c7', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 38, 38, 'Behold, your house is left to you desolate.'),
  ('f542ae21-6a29-5106-af38-fbf1edac50fc', '999a0e91-15ea-54d1-aad8-16e2e3919964', NULL, 39, 39, 'For I tell you, you will not see me from now on, until you say, ''Blessed is he who comes in the name of the Lord!''"'),
  ('8078a99e-a825-5152-a12a-6d8df67260bc', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 1, 1, 'Jesus went out from the temple, and was going on his way. His disciples came to him to show him the buildings of the temple.'),
  ('127f8dbf-8fc6-5037-a1a3-924b2c6f2113', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 2, 2, 'But he answered them, "You see all of these things, don''t you? Most certainly I tell you, there will not be left here one stone on another, that will not be thrown down."'),
  ('e95b643a-fe11-514a-a537-a49ae8a89e3d', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 3, 3, 'As he sat on the Mount of Olives, the disciples came to him privately, saying, "Tell us, when will these things be? What is the sign of your coming, and of the end of the age?"'),
  ('53902031-9638-5ce8-a81f-4c1fd5b53c93', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 4, 4, 'Jesus answered them, "Be careful that no one leads you astray.'),
  ('fea35cda-5545-5652-a3d2-a84d9430a46b', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 5, 5, 'For many will come in my name, saying, ''I am the Christ,'' and will lead many astray.'),
  ('a18b1621-abdb-5051-af00-1a11b8434889', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 6, 6, 'You will hear of wars and rumors of wars. See that you aren''t troubled, for all this must happen, but the end is not yet.'),
  ('f9c9d588-c278-55f5-ac17-9c5f11de60cb', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 7, 7, 'For nation will rise against nation, and kingdom against kingdom; and there will be famines, plagues, and earthquakes in various places.'),
  ('105ac9cb-d7ee-5190-a223-34b44e73bb89', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 8, 8, 'But all these things are the beginning of birth pains.'),
  ('1828d76b-ad67-54f9-a531-daef1d9632e2', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 9, 9, 'Then they will deliver you up to oppression, and will kill you. You will be hated by all of the nations for my name''s sake.'),
  ('63151ee0-0889-5610-a63a-a3cc68fd5515', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 10, 10, 'Then many will stumble, and will deliver up one another, and will hate one another.'),
  ('76140f62-6085-5c55-a647-69e7bd5b3170', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 11, 11, 'Many false prophets will arise, and will lead many astray.'),
  ('57a56978-1aea-5c05-a10e-62fa1b01b75d', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 12, 12, 'Because iniquity will be multiplied, the love of many will grow cold.'),
  ('86939a49-8184-5fa7-a5d8-68127da01a24', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 13, 13, 'But he who endures to the end, the same will be saved.'),
  ('94e8277a-aab0-5c09-a736-cb201f657888', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 14, 14, 'This Good News of the Kingdom will be preached in the whole world for a testimony to all the nations, and then the end will come.'),
  ('a7d630ae-c873-5e6f-a314-c4465eb3ba49', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 15, 15, '"When, therefore, you see the abomination of desolation, which was spoken of through Daniel the prophet, standing in the holy place (let the reader understand),'),
  ('22e700e1-1dde-5d59-adb0-470c28d6fa60', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 16, 16, 'then let those who are in Judea flee to the mountains.'),
  ('706e7853-6253-5e9f-a488-ada0f7a0f2be', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 17, 17, 'Let him who is on the housetop not go down to take out things that are in his house.'),
  ('30c17989-56ea-50ac-a39b-823b00cf7a85', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 18, 18, 'Let him who is in the field not return back to get his clothes.'),
  ('a7baa084-53c4-5c21-a550-c3ea8e127583', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 19, 19, 'But woe to those who are with child and to nursing mothers in those days!'),
  ('b07dbb57-b0bc-5b07-a0eb-97ae26d569ed', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 20, 20, 'Pray that your flight will not be in the winter, nor on a Sabbath,'),
  ('92c11492-7fa8-5d32-a1b2-e67a4f31043b', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 21, 21, 'for then there will be great oppression, such as has not been from the beginning of the world until now, no, nor ever will be.'),
  ('e671e56b-9668-5b4d-aacb-39e36d37b62d', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 22, 22, 'Unless those days had been shortened, no flesh would have been saved. But for the sake of the chosen ones, those days will be shortened.'),
  ('855e5cc8-905f-59c5-acf3-5665cd2e3b78', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 23, 23, '"Then if any man tells you, ''Behold, here is the Christ,'' or, ''There,'' don''t believe it.'),
  ('172696d3-c66a-53a6-a588-3b15245ddc8a', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 24, 24, 'For there will arise false christs, and false prophets, and they will show great signs and wonders, so as to lead astray, if possible, even the chosen ones.'),
  ('0b06c59e-f4d4-516e-a854-4f1295a6ba57', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 25, 25, '"Behold, I have told you beforehand.'),
  ('739d5e84-a35e-5000-a473-d2d086ce5439', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 26, 26, 'If therefore they tell you, ''Behold, he is in the wilderness,'' don''t go out; ''Behold, he is in the inner rooms,'' don''t believe it.'),
  ('b70f6106-5bbd-5e24-ac2c-70757889c329', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 27, 27, 'For as the lightning flashes from the east, and is seen even to the west, so will be the coming of the Son of Man.'),
  ('3750e86c-02b1-5ade-a7e2-d434d15f886f', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 28, 28, 'For wherever the carcass is, there is where the vultures gather together.'),
  ('d34fd09a-23c8-5011-ab84-c5ff65486663', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 29, 29, 'But immediately after the oppression of those days, the sun will be darkened, the moon will not give its light, the stars will fall from the sky, and the powers of the heavens will be shaken;'),
  ('c865176d-bf76-598d-a4be-460bce7b0eca', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 30, 30, 'and then the sign of the Son of Man will appear in the sky. Then all the tribes of the earth will mourn, and they will see the Son of Man coming on the clouds of the sky with power and great glory.'),
  ('355e175f-a93b-5421-a0d7-11e146c87cf8', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 31, 31, 'He will send out his angels with a great sound of a trumpet, and they will gather together his chosen ones from the four winds, from one end of the sky to the other.'),
  ('c8953bc0-ba62-5fa4-a5c0-de648cdd6bf0', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 32, 32, '"Now from the fig tree learn this parable. When its branch has now become tender, and puts forth its leaves, you know that the summer is near.'),
  ('e2115722-e731-5386-affb-cae97dbf4660', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 33, 33, 'Even so you also, when you see all these things, know that it is near, even at the doors.'),
  ('2b1df576-3285-5351-a574-3e874f5a37b7', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 34, 34, 'Most certainly I tell you, this generation will not pass away, until all these things are accomplished.'),
  ('4bf9c310-5c61-5f9a-a71c-b8b97851770a', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 35, 35, 'Heaven and earth will pass away, but my words will not pass away.'),
  ('a77acab2-bf1e-5d1a-adec-2ae8765538c8', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 36, 36, 'But no one knows of that day and hour, not even the angels of heaven, but my Father only.'),
  ('3fb5ce11-eb71-5733-afe6-ec96f794646d', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 37, 37, '"As the days of Noah were, so will be the coming of the Son of Man.'),
  ('dcad6a5f-52ed-5939-ab3c-6ccc30245a84', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 38, 38, 'For as in those days which were before the flood they were eating and drinking, marrying and giving in marriage, until the day that Noah entered into the ship,'),
  ('ca0791e8-1d41-5beb-a03e-4aa729b9c487', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 39, 39, 'and they didn''t know until the flood came, and took them all away, so will be the coming of the Son of Man.'),
  ('aa5f7040-1bba-5922-abcd-3c96336c5477', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 40, 40, 'Then two men will be in the field: one will be taken and one will be left;'),
  ('cb4847e8-f975-5960-a4e3-e7f0f1ecdceb', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 41, 41, 'two women grinding at the mill, one will be taken and one will be left.'),
  ('5bab13af-8fd6-5304-a392-2d25e609445e', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 42, 42, 'Watch therefore, for you don''t know in what hour your Lord comes.'),
  ('a3288bdf-7fa1-54f6-a3ba-ed17ea8c2068', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 43, 43, 'But know this, that if the master of the house had known in what watch of the night the thief was coming, he would have watched, and would not have allowed his house to be broken into.'),
  ('0eca6527-f53b-592a-a47c-dd60c74eb463', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 44, 44, 'Therefore also be ready, for in an hour that you don''t expect, the Son of Man will come.'),
  ('3de27480-9ff9-5eec-a70e-510f159df002', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 45, 45, '"Who then is the faithful and wise servant, whom his lord has set over his household, to give them their food in due season?'),
  ('2e1c1d2a-f1e3-5271-adbd-0261b6063c5f', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 46, 46, 'Blessed is that servant whom his lord finds doing so when he comes.'),
  ('25c6b16f-dfa1-5566-ac3f-a745657454d6', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 47, 47, 'Most certainly I tell you that he will set him over all that he has.'),
  ('96815053-34f0-5c9a-ad53-400b71e191e6', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 48, 48, 'But if that evil servant should say in his heart, ''My lord is delaying his coming,'''),
  ('6e4a7d3c-f1a0-580a-af85-1d831173d294', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 49, 49, 'and begins to beat his fellow servants, and eat and drink with the drunkards,'),
  ('b20f04d9-fa4e-5509-a4df-97edd1df66f2', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 50, 50, 'the lord of that servant will come in a day when he doesn''t expect it, and in an hour when he doesn''t know it,'),
  ('69430c86-6512-5504-af8e-fed405e3ed88', '1eee7762-7006-5ab1-ac8f-0b71d39e0ac2', NULL, 51, 51, 'and will cut him in pieces, and appoint his portion with the hypocrites. There is where the weeping and grinding of teeth will be.'),
  ('927897c8-8297-53c9-af3b-54281b5977b0', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 1, 1, '"Then the Kingdom of Heaven will be like ten virgins, who took their lamps, and went out to meet the bridegroom.'),
  ('94a2153d-2acf-522b-a3fd-fb4dbc094938', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 2, 2, 'Five of them were foolish, and five were wise.'),
  ('698b50e1-2aae-5d6e-a854-8ce764774f66', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 3, 3, 'Those who were foolish, when they took their lamps, took no oil with them,'),
  ('960e67ef-2d21-5e09-a58f-6a1c921bf302', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 4, 4, 'but the wise took oil in their vessels with their lamps.'),
  ('16567e2c-1ffe-529f-a836-178d892b4e4b', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 5, 5, 'Now while the bridegroom delayed, they all slumbered and slept.'),
  ('3d4a2e6a-e1e2-55a7-a504-e60b8926343a', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 6, 6, 'But at midnight there was a cry, ''Behold! The bridegroom is coming! Come out to meet him!'''),
  ('c4a84e12-1f38-5055-afc1-5d0b43e3e8b3', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 7, 7, 'Then all those virgins arose, and trimmed their lamps.'),
  ('201cb405-b55a-5ab3-a1ef-170168ca87fc', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 8, 8, 'The foolish said to the wise, ''Give us some of your oil, for our lamps are going out.'''),
  ('21ce4b3c-9ab3-5291-affc-71785a6f4199', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 9, 9, 'But the wise answered, saying, ''What if there isn''t enough for us and you? You go rather to those who sell, and buy for yourselves.'''),
  ('6dc22850-66ac-5c97-a637-cdff8de9594c', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 10, 10, 'While they went away to buy, the bridegroom came, and those who were ready went in with him to the marriage feast, and the door was shut.'),
  ('912a6dcf-589a-5bce-a6e1-3f629dc7e0a8', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 11, 11, 'Afterward the other virgins also came, saying, ''Lord, Lord, open to us.'''),
  ('aaad4462-f4f7-5539-acab-e0c92d835f12', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 12, 12, 'But he answered, ''Most certainly I tell you, I don''t know you.'''),
  ('8aaefd0a-4e74-53a1-aa86-05aa8797424c', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 13, 13, 'Watch therefore, for you don''t know the day nor the hour in which the Son of Man is coming.'),
  ('3c992995-3dbf-57da-a42a-83e2e75f7e25', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 14, 14, '"For it is like a man, going into another country, who called his own servants, and entrusted his goods to them.'),
  ('49ffc7bc-4396-509f-a11f-3df070752858', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 15, 15, 'To one he gave five talents, to another two, to another one; to each according to his own ability. Then he went on his journey.'),
  ('16fbdbcd-a608-53cd-ab21-c6248f955ce6', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 16, 16, 'Immediately he who received the five talents went and traded with them, and made another five talents.'),
  ('f2a8a1e9-1259-5134-a04e-a531a696bc6a', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 17, 17, 'In the same way, he also who got the two gained another two.'),
  ('810d0aff-ea65-59a6-a224-797669531f9c', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 18, 18, 'But he who received the one went away and dug in the earth, and hid his lord''s money.'),
  ('db365768-feea-5005-ac8f-4b54b9515e8d', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 19, 19, '"Now after a long time the lord of those servants came, and reconciled accounts with them.'),
  ('8e1d8362-4474-5c27-aeba-a24638108420', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 20, 20, 'He who received the five talents came and brought another five talents, saying, ''Lord, you delivered to me five talents. Behold, I have gained another five talents besides them.'''),
  ('cd96e8d0-833b-52c6-a637-b68ad55927c5', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 21, 21, '"His lord said to him, ''Well done, good and faithful servant. You have been faithful over a few things, I will set you over many things. Enter into the joy of your lord.'''),
  ('dbaadaf5-4593-5395-ac6c-5a0c53425a71', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 22, 22, '"He also who got the two talents came and said, ''Lord, you delivered to me two talents. Behold, I have gained another two talents besides them.'''),
  ('d68436ed-f870-5ad6-a1b0-88d1bb22a1b7', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 23, 23, '"His lord said to him, ''Well done, good and faithful servant. You have been faithful over a few things, I will set you over many things. Enter into the joy of your lord.'''),
  ('0af11143-6ffc-539f-a9b9-0af07f901274', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 24, 24, '"He also who had received the one talent came and said, ''Lord, I knew you that you are a hard man, reaping where you did not sow, and gathering where you did not scatter.'),
  ('57345b19-21f6-5299-a652-0b896344eda4', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 25, 25, 'I was afraid, and went away and hid your talent in the earth. Behold, you have what is yours.'''),
  ('68f4251e-85b4-5482-a2f3-5335dce382a7', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 26, 26, '"But his lord answered him, ''You wicked and slothful servant. You knew that I reap where I didn''t sow, and gather where I didn''t scatter.'),
  ('d27896fe-1e9d-5ff7-a291-ddabbbb36f8d', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 27, 27, 'You ought therefore to have deposited my money with the bankers, and at my coming I should have received back my own with interest.'),
  ('8dc408ab-e434-5dae-a7aa-114e21febf4e', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 28, 28, 'Take away therefore the talent from him, and give it to him who has the ten talents.'),
  ('d41a551c-55de-5e3c-a2ba-2d6d079f0dcc', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 29, 29, 'For to everyone who has will be given, and he will have abundance, but from him who doesn''t have, even that which he has will be taken away.'),
  ('0e2095c4-86b3-52a5-a44c-7f567c419b46', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 30, 30, 'Throw out the unprofitable servant into the outer darkness, where there will be weeping and gnashing of teeth.'''),
  ('9cb0f6f2-8a08-5bd8-a1e2-0fb061dc988e', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 31, 31, '"But when the Son of Man comes in his glory, and all the holy angels with him, then he will sit on the throne of his glory.'),
  ('2d14f3c9-810e-5708-addb-8ac0a6515eba', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 32, 32, 'Before him all the nations will be gathered, and he will separate them one from another, as a shepherd separates the sheep from the goats.'),
  ('b64a1a82-1348-5e83-ad05-51966540dc3c', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 33, 33, 'He will set the sheep on his right hand, but the goats on the left.'),
  ('80aa5d9b-88cd-5123-abda-a21e081b567d', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 34, 34, 'Then the King will tell those on his right hand, ''Come, blessed of my Father, inherit the Kingdom prepared for you from the foundation of the world;'),
  ('31733537-8a7c-5caa-ae18-6896901441d6', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 35, 35, 'for I was hungry, and you gave me food to eat. I was thirsty, and you gave me drink. I was a stranger, and you took me in.'),
  ('47a17a3b-edb8-59cb-a98d-3236f5b5ebc6', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 36, 36, 'I was naked, and you clothed me. I was sick, and you visited me. I was in prison, and you came to me.'''),
  ('7a8d6c1d-0925-5cad-a482-c1e363aca181', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 37, 37, '"Then the righteous will answer him, saying, ''Lord, when did we see you hungry, and feed you; or thirsty, and give you a drink?'),
  ('0f73cd3b-d31e-5122-aeca-a13a2a79b46a', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 38, 38, 'When did we see you as a stranger, and take you in; or naked, and clothe you?'),
  ('456d2043-5497-56b8-a9ef-007d8c99d634', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 39, 39, 'When did we see you sick, or in prison, and come to you?'''),
  ('783dd354-e537-55e6-a5fc-59dd87454421', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 40, 40, '"The King will answer them, ''Most certainly I tell you, inasmuch as you did it to one of the least of these my brothers, you did it to me.'''),
  ('7b0a4962-bff0-56df-ae7a-d5e389f2d2a6', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 41, 41, 'Then he will say also to those on the left hand, ''Depart from me, you cursed, into the eternal fire which is prepared for the devil and his angels;'),
  ('5dd183db-d6aa-549e-aacc-9cf8b3d46f55', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 42, 42, 'for I was hungry, and you didn''t give me food to eat; I was thirsty, and you gave me no drink;'),
  ('d0904093-9447-5c99-af56-aa89e41bbf8f', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 43, 43, 'I was a stranger, and you didn''t take me in; naked, and you didn''t clothe me; sick, and in prison, and you didn''t visit me.'''),
  ('70b8688a-2295-56b1-a0c0-93e685e96a02', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 44, 44, '"Then they will also answer, saying, ''Lord, when did we see you hungry, or thirsty, or a stranger, or naked, or sick, or in prison, and didn''t help you?'''),
  ('54b1c0f4-c3de-5ba4-a0ad-a10000f536f0', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 45, 45, '"Then he will answer them, saying, ''Most certainly I tell you, inasmuch as you didn''t do it to one of the least of these, you didn''t do it to me.'''),
  ('ceb842e5-1863-52c0-a316-df40a3b06157', '56fcc241-980f-5777-a9d4-03bd5e1f362f', NULL, 46, 46, 'These will go away into eternal punishment, but the righteous into eternal life."'),
  ('29a9d08b-f8f2-506f-ac50-50d9275c3b5b', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 1, 1, 'It happened, when Jesus had finished all these words, that he said to his disciples,'),
  ('7de4d62a-bcfe-5654-a97c-0f9dbb32e209', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 2, 2, '"You know that after two days the Passover is coming, and the Son of Man will be delivered up to be crucified."'),
  ('da54f065-797d-5c83-a5c6-bde64a4f6642', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 3, 3, 'Then the chief priests, the scribes, and the elders of the people were gathered together in the court of the high priest, who was called Caiaphas.'),
  ('43a9c3c9-5e77-5109-a3ef-ba7bc559217a', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 4, 4, 'They took counsel together that they might take Jesus by deceit, and kill him.'),
  ('1e9b270a-05fa-5bcb-add3-84970d9f0643', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 5, 5, 'But they said, "Not during the feast, lest a riot occur among the people."'),
  ('9be5538c-8a12-53ac-ad4d-d06b00329a17', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 6, 6, 'Now when Jesus was in Bethany, in the house of Simon the leper,'),
  ('75f715b0-fe59-5d19-ab9f-67f2d04f88b5', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 7, 7, 'a woman came to him having an alabaster jar of very expensive ointment, and she poured it on his head as he sat at the table.'),
  ('7168d569-59c5-5b8c-a6e8-5e788a7cba1b', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 8, 8, 'But when his disciples saw this, they were indignant, saying, "Why this waste?'),
  ('547213ab-16d1-5b3e-a2d7-a3ae2b273cae', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 9, 9, 'For this ointment might have been sold for much, and given to the poor."'),
  ('09284400-aba8-56fe-aa18-19159e94cb8c', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 10, 10, 'However, knowing this, Jesus said to them, "Why do you trouble the woman? Because she has done a good work for me.'),
  ('73d580b0-bec0-5354-abb8-d02d33548eee', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 11, 11, 'For you always have the poor with you; but you don''t always have me.'),
  ('99848ded-ac06-5b1c-ac4c-2196bd6efa6e', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 12, 12, 'For in pouring this ointment on my body, she did it to prepare me for burial.'),
  ('daf8bfc8-7c26-59a3-a5ba-6f3f2df8f6ca', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 13, 13, 'Most certainly I tell you, wherever this Good News is preached in the whole world, what this woman has done will also be spoken of as a memorial of her."'),
  ('7131564f-a303-5caf-a630-9209a24231fd', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 14, 14, 'Then one of the twelve, who was called Judas Iscariot, went to the chief priests,'),
  ('cbdda74f-4ce3-5db5-a80c-9c70228ab7e0', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 15, 15, 'and said, "What are you willing to give me, that I should deliver him to you?" They weighed out for him thirty pieces of silver.'),
  ('06177f4b-04d7-58a2-a120-55b256f9b1fa', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 16, 16, 'From that time he sought opportunity to betray him.'),
  ('f5fcc157-cfd8-57c3-a1d1-76c219c97604', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 17, 17, 'Now on the first day of unleavened bread, the disciples came to Jesus, saying to him, "Where do you want us to prepare for you to eat the Passover?"'),
  ('aba1480b-698a-5fd1-a9aa-c01f911f8439', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 18, 18, 'He said, "Go into the city to a certain person, and tell him, ''The Teacher says, "My time is at hand. I will keep the Passover at your house with my disciples."''"'),
  ('04657591-0dfd-5378-a58c-66e244eca2b2', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 19, 19, 'The disciples did as Jesus commanded them, and they prepared the Passover.'),
  ('74caa254-bcf6-5424-a740-1340bef42c7d', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 20, 20, 'Now when evening had come, he was reclining at the table with the twelve disciples.'),
  ('a023f89a-9f90-5588-a5b0-9f4d8bfe83d5', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 21, 21, 'As they were eating, he said, "Most certainly I tell you that one of you will betray me."'),
  ('70a9c56d-7e02-54fe-a65e-aac11ae3feba', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 22, 22, 'They were exceedingly sorrowful, and each began to ask him, "It isn''t me, is it, Lord?"'),
  ('35b93eb7-8f56-583a-a646-39c6aae7bb96', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 23, 23, 'He answered, "He who dipped his hand with me in the dish, the same will betray me.'),
  ('f9509f1e-2454-5425-a9e8-94c23a0040b8', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 24, 24, 'The Son of Man goes, even as it is written of him, but woe to that man through whom the Son of Man is betrayed! It would be better for that man if he had not been born."'),
  ('89532966-7f52-56eb-a6b5-24c468e51d35', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 25, 25, 'Judas, who betrayed him, answered, "It isn''t me, is it, Rabbi?" He said to him, "You said it."'),
  ('5da4f1df-58e7-517a-a774-5107037d7e21', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 26, 26, 'As they were eating, Jesus took bread, gave thanks for it, and broke it. He gave to the disciples, and said, "Take, eat; this is my body."'),
  ('1c81aaeb-4f7d-5345-a39d-1d20c7f7f09b', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 27, 27, 'He took the cup, gave thanks, and gave to them, saying, "All of you drink it,'),
  ('b66181bc-bfd8-5a94-a2c4-27fdbb55faad', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 28, 28, 'for this is my blood of the new covenant, which is poured out for many for the remission of sins.'),
  ('8036028d-0157-53fa-a4f5-f99bcbb91a51', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 29, 29, 'But I tell you that I will not drink of this fruit of the vine from now on, until that day when I drink it anew with you in my Father''s Kingdom."'),
  ('259c57a7-eeb9-5dfd-ac4f-cbe3dd729c39', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 30, 30, 'When they had sung a hymn, they went out to the Mount of Olives.'),
  ('e9b37925-2595-5218-a623-c24566e89f7c', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 31, 31, 'Then Jesus said to them, "All of you will be made to stumble because of me tonight, for it is written, ''I will strike the shepherd, and the sheep of the flock will be scattered.'''),
  ('35bb9fef-56e7-591e-a344-18b0b8cf5333', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 32, 32, 'But after I am raised up, I will go before you into Galilee."'),
  ('60d98448-b7b9-52da-ac41-4267be58aae6', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 33, 33, 'But Peter answered him, "Even if all will be made to stumble because of you, I will never be made to stumble."'),
  ('bc650df5-d2c0-5c2e-a1bb-66180c4677b3', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 34, 34, 'Jesus said to him, "Most certainly I tell you that tonight, before the rooster crows, you will deny me three times."'),
  ('ded5f57c-6b0b-5118-a484-15c36e9e060b', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 35, 35, 'Peter said to him, "Even if I must die with you, I will not deny you." All of the disciples also said likewise.'),
  ('3aab009b-416f-56ab-aad4-0ad6ca8dcb21', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 36, 36, 'Then Jesus came with them to a place called Gethsemane, and said to his disciples, "Sit here, while I go there and pray."'),
  ('d9de2616-e3a9-5c42-a2cf-045dd8f6a5db', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 37, 37, 'He took with him Peter and the two sons of Zebedee, and began to be sorrowful and severely troubled.'),
  ('200418d7-b013-53fe-a016-f44cff298bbf', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 38, 38, 'Then he said to them, "My soul is exceedingly sorrowful, even to death. Stay here, and watch with me."'),
  ('dd96d604-d0b7-57bb-ab53-cb656d3d4b51', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 39, 39, 'He went forward a little, fell on his face, and prayed, saying, "My Father, if it is possible, let this cup pass away from me; nevertheless, not what I desire, but what you desire."'),
  ('93bed817-a107-5ac8-aaff-9c003bbdce92', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 40, 40, 'He came to the disciples, and found them sleeping, and said to Peter, "What, couldn''t you watch with me for one hour?'),
  ('58c849a9-517a-5fb1-aaea-475d5b2c4ea5', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 41, 41, 'Watch and pray, that you don''t enter into temptation. The spirit indeed is willing, but the flesh is weak."'),
  ('002f2739-f407-583d-a0eb-9e3033dbeeee', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 42, 42, 'Again, a second time he went away, and prayed, saying, "My Father, if this cup can''t pass away from me unless I drink it, your desire be done."'),
  ('bf36241f-794e-5bfe-a34d-bb2bec4aaa81', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 43, 43, 'He came again and found them sleeping, for their eyes were heavy.'),
  ('0690bfb4-c751-595a-ae49-ecb142663424', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 44, 44, 'He left them again, went away, and prayed a third time, saying the same words.'),
  ('9e3353f6-3d3d-5bda-a1a4-a6910181112a', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 45, 45, 'Then he came to his disciples, and said to them, "Sleep on now, and take your rest. Behold, the hour is at hand, and the Son of Man is betrayed into the hands of sinners.'),
  ('4a4f9c97-a7d0-540e-ac27-070806b05c4d', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 46, 46, 'Arise, let''s be going. Behold, he who betrays me is at hand."'),
  ('68d6d03f-4c62-57b9-ae08-a65a0ffca59e', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 47, 47, 'While he was still speaking, behold, Judas, one of the twelve, came, and with him a great multitude with swords and clubs, from the chief priest and elders of the people.'),
  ('3dbcb588-d804-5cef-af21-04eed65ecaf4', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 48, 48, 'Now he who betrayed him gave them a sign, saying, "Whoever I kiss, he is the one. Seize him."'),
  ('19fed04b-e2f6-5fe2-a675-f78407b34c99', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 49, 49, 'Immediately he came to Jesus, and said, "Hail, Rabbi!" and kissed him.'),
  ('f44a7955-885a-5af5-a170-406cc8d65027', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 50, 50, 'Jesus said to him, "Friend, why are you here?" Then they came and laid hands on Jesus, and took him.'),
  ('18536ee3-628c-5ffc-aeba-2e4c8d05a4de', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 51, 51, 'Behold, one of those who were with Jesus stretched out his hand, and drew his sword, and struck the servant of the high priest, and struck off his ear.'),
  ('d0d0bdb9-9b30-5a7d-a4df-a9b7ee8824ab', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 52, 52, 'Then Jesus said to him, "Put your sword back into its place, for all those who take the sword will die by the sword.'),
  ('e76a480f-1e0e-5c5f-a52d-3a03a5d940ca', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 53, 53, 'Or do you think that I couldn''t ask my Father, and he would even now send me more than twelve legions of angels?'),
  ('ff63fe7f-2fab-5e5a-af3a-f1fcff7a6642', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 54, 54, 'How then would the Scriptures be fulfilled that it must be so?"'),
  ('06f2e6f4-6b8a-5c1e-a7bd-1301a682aef2', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 55, 55, 'In that hour Jesus said to the multitudes, "Have you come out as against a robber with swords and clubs to seize me? I sat daily in the temple teaching, and you didn''t arrest me.'),
  ('f27f41e3-3fa4-5042-ac58-34522ae33319', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 56, 56, 'But all this has happened, that the Scriptures of the prophets might be fulfilled." Then all the disciples left him, and fled.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('338aa4a6-bcec-551e-a265-0ea622f66a1f', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 57, 57, 'Those who had taken Jesus led him away to Caiaphas the high priest, where the scribes and the elders were gathered together.'),
  ('281a557c-f842-5c2f-a28b-dae6324c5bdd', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 58, 58, 'But Peter followed him from a distance, to the court of the high priest, and entered in and sat with the officers, to see the end.'),
  ('d0ccfcbb-4a18-59bf-a4b9-8e5a81dcf907', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 59, 59, 'Now the chief priests, the elders, and the whole council sought false testimony against Jesus, that they might put him to death;'),
  ('d4765c85-a398-5993-ae26-9bb7ddb62b5e', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 60, 60, 'and they found none. Even though many false witnesses came forward, they found none. But at last two false witnesses came forward,'),
  ('1417f0fd-cf74-5470-a45d-071132ab505c', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 61, 61, 'and said, "This man said, ''I am able to destroy the temple of God, and to build it in three days.''"'),
  ('a0ea10d6-90c7-5e76-ae72-efe619716e2d', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 62, 62, 'The high priest stood up, and said to him, "Have you no answer? What is this that these testify against you?"'),
  ('42732f86-a2c9-5523-a61c-2fcc9ba83351', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 63, 63, 'But Jesus held his peace. The high priest answered him, "I adjure you by the living God, that you tell us whether you are the Christ, the Son of God."'),
  ('dedd2d20-340e-5d49-a9e5-7e55cd66c346', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 64, 64, 'Jesus said to him, "You have said it. Nevertheless, I tell you, after this you will see the Son of Man sitting at the right hand of Power, and coming on the clouds of the sky."'),
  ('62d33514-1958-585c-abd5-85db98cba204', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 65, 65, 'Then the high priest tore his clothing, saying, "He has spoken blasphemy! Why do we need any more witnesses? Behold, now you have heard his blasphemy.'),
  ('69cc6df1-03a0-595c-aa33-8fda4e01047b', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 66, 66, 'What do you think?" They answered, "He is worthy of death!"'),
  ('d3dbab07-0060-55ef-a578-e292f74a20d4', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 67, 67, 'Then they spit in his face and beat him with their fists, and some slapped him,'),
  ('b0a143e5-9a8a-5e70-a256-f3e44ad2a867', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 68, 68, 'saying, "Prophesy to us, you Christ! Who hit you?"'),
  ('de8bd19b-1ac9-5035-adff-0562b461ff24', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 69, 69, 'Now Peter was sitting outside in the court, and a maid came to him, saying, "You were also with Jesus, the Galilean!"'),
  ('2cc227c6-e121-5e76-ab2d-c88b46e8c0e3', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 70, 70, 'But he denied it before them all, saying, "I don''t know what you are talking about."'),
  ('122f899c-6355-5d10-a332-9f9d2a0b7306', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 71, 71, 'When he had gone out onto the porch, someone else saw him, and said to those who were there, "This man also was with Jesus of Nazareth."'),
  ('17001010-3569-5f48-a67c-f071a4f6482a', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 72, 72, 'Again he denied it with an oath, "I don''t know the man."'),
  ('3c836576-a623-5bc9-a207-913d58f7ae9f', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 73, 73, 'After a little while those who stood by came and said to Peter, "Surely you are also one of them, for your speech makes you known."'),
  ('d3b29d56-bd11-574e-a372-f265ee120800', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 74, 74, 'Then he began to curse and to swear, "I don''t know the man!" Immediately the rooster crowed.'),
  ('d244f93e-33d3-59bf-a1a2-21a243f6d38e', '81e3882d-e54f-5f8c-a1dd-9d5357f89de2', NULL, 75, 75, 'Peter remembered the word which Jesus had said to him, "Before the rooster crows, you will deny me three times." He went out and wept bitterly.'),
  ('f4165a4c-236c-5978-adde-2acdd50f0e46', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 1, 1, 'Now when morning had come, all the chief priests and the elders of the people took counsel against Jesus to put him to death:'),
  ('7d58d7ad-0120-58a4-a4fe-31260be70eb8', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 2, 2, 'and they bound him, and led him away, and delivered him up to Pontius Pilate, the governor.'),
  ('1b454cad-1835-5304-a0e0-a290cc252bdf', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 3, 3, 'Then Judas, who betrayed him, when he saw that Jesus was condemned, felt remorse, and brought back the thirty pieces of silver to the chief priests and elders,'),
  ('94e9c57e-2626-5ca7-a7d3-e6eb6e28bf3b', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 4, 4, 'saying, "I have sinned in that I betrayed innocent blood." But they said, "What is that to us? You see to it."'),
  ('01d8206e-532d-5615-a7ce-b284e3f51b3e', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 5, 5, 'He threw down the pieces of silver in the sanctuary, and departed. He went away and hanged himself.'),
  ('04c84183-6509-55d8-abef-3da47cc7b093', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 6, 6, 'The chief priests took the pieces of silver, and said, "It''s not lawful to put them into the treasury, since it is the price of blood."'),
  ('7d6f4edc-1649-55ce-a300-887655aeb5bf', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 7, 7, 'They took counsel, and bought the potter''s field with them, to bury strangers in.'),
  ('24e492dd-8c0d-5c87-a21a-61fd4ecb853b', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 8, 8, 'Therefore that field was called "The Field of Blood" to this day.'),
  ('695a2842-5bff-5247-a658-1b4ce71e2b00', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 9, 9, 'Then that which was spoken through Jeremiah the prophet was fulfilled, saying, "They took the thirty pieces of silver, the price of him upon whom a price had been set, whom some of the children of Israel priced,'),
  ('f858fd21-d7cf-5f3d-a4e1-2e21959d23b0', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 10, 10, 'and they gave them for the potter''s field, as the Lord commanded me."'),
  ('5e58d14b-ab74-56b6-a4b9-0d6bdb258a08', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 11, 11, 'Now Jesus stood before the governor: and the governor asked him, saying, "Are you the King of the Jews?" Jesus said to him, "So you say."'),
  ('9f318beb-e64b-5b60-add1-4e5b793c9896', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 12, 12, 'When he was accused by the chief priests and elders, he answered nothing.'),
  ('d807d087-35de-5139-a809-0b1492f9dd8a', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 13, 13, 'Then Pilate said to him, "Don''t you hear how many things they testify against you?"'),
  ('95d904b9-5b4d-5bbd-a7bf-4c0e5782146e', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 14, 14, 'He gave him no answer, not even one word, so that the governor marveled greatly.'),
  ('d06d5ccb-bed6-5c9b-a0ef-e49d39cd8c42', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 15, 15, 'Now at the feast the governor was accustomed to release to the multitude one prisoner, whom they desired.'),
  ('21aba81d-ee01-5f48-a0e5-52c1bf083d33', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 16, 16, 'They had then a notable prisoner, called Barabbas.'),
  ('098f3c93-3e37-50ad-a927-3c16217a9503', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 17, 17, 'When therefore they were gathered together, Pilate said to them, "Whom do you want me to release to you? Barabbas, or Jesus, who is called Christ?"'),
  ('147ebc2c-219c-5889-ac01-a8dc2cf81e4b', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 18, 18, 'For he knew that because of envy they had delivered him up.'),
  ('a23c25b6-511c-5cc5-a973-6962e29c9ea7', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 19, 19, 'While he was sitting on the judgment seat, his wife sent to him, saying, "Have nothing to do with that righteous man, for I have suffered many things this day in a dream because of him."'),
  ('c02776d7-134e-59c6-ae02-f67ba3971429', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 20, 20, 'Now the chief priests and the elders persuaded the multitudes to ask for Barabbas, and destroy Jesus.'),
  ('cdbf92be-ad9c-5583-af7a-f282fa280671', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 21, 21, 'But the governor answered them, "Which of the two do you want me to release to you?" They said, "Barabbas!"'),
  ('a13107b5-8d77-5664-ace5-3a6a671f0d05', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 22, 22, 'Pilate said to them, "What then shall I do to Jesus, who is called Christ?" They all said to him, "Let him be crucified!"'),
  ('7ec76aa7-9f1f-5953-a147-bfbb35d833b0', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 23, 23, 'But the governor said, "Why? What evil has he done?" But they cried out exceedingly, saying, "Let him be crucified!"'),
  ('cdf10214-1a14-5317-a183-2340ac888edf', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 24, 24, 'So when Pilate saw that nothing was being gained, but rather that a disturbance was starting, he took water, and washed his hands before the multitude, saying, "I am innocent of the blood of this righteous person. You see to it."'),
  ('e930001f-d856-583c-a293-504e72942791', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 25, 25, 'All the people answered, "May his blood be on us, and on our children!"'),
  ('23212a47-496b-52ab-af6a-4c77bea53b09', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 26, 26, 'Then he released to them Barabbas, but Jesus he flogged and delivered to be crucified.'),
  ('37478cf0-5962-5fd1-aa6c-4ae6ec2ce0e8', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 27, 27, 'Then the governor''s soldiers took Jesus into the Praetorium, and gathered the whole garrison together against him.'),
  ('6a0a5d41-0a31-5499-a7b9-741f4e86d661', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 28, 28, 'They stripped him, and put a scarlet robe on him.'),
  ('68d4cd48-a046-56ce-af02-a826c36fedef', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 29, 29, 'They braided a crown of thorns and put it on his head, and a reed in his right hand; and they kneeled down before him, and mocked him, saying, "Hail, King of the Jews!"'),
  ('aaa12685-729a-55b1-aa47-65b2171751db', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 30, 30, 'They spat on him, and took the reed and struck him on the head.'),
  ('07d504df-c6f3-5fd6-a1f6-294c831ce591', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 31, 31, 'When they had mocked him, they took the robe off of him, and put his clothes on him, and led him away to crucify him.'),
  ('913b3ee0-65f0-53fa-a69a-9fb9afa6245d', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 32, 32, 'As they came out, they found a man of Cyrene, Simon by name, and they compelled him to go with them, that he might carry his cross.'),
  ('450542a2-dc2c-5cc4-ad4a-daa77707f950', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 33, 33, 'They came to a place called "Golgotha," that is to say, "The place of a skull."'),
  ('30a90574-a24c-5362-a542-5515342bce24', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 34, 34, 'They gave him sour wine to drink mixed with gall. When he had tasted it, he would not drink.'),
  ('4a3b8065-9dde-5651-aebc-dcd7e147caf3', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 35, 35, 'When they had crucified him, they divided his clothing among them, casting lots,'),
  ('ea1cf409-db1a-5c65-a2e2-af78644a9878', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 36, 36, 'and they sat and watched him there.'),
  ('5321ed31-bb75-5633-a341-24ad500373bc', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 37, 37, 'They set up over his head the accusation against him written, "THIS IS JESUS, THE KING OF THE JEWS."'),
  ('b8d6f47e-af4b-5d69-afaa-85394752d071', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 38, 38, 'Then there were two robbers crucified with him, one on his right hand and one on the left.'),
  ('6e7d9b2b-5b7d-53e7-aad8-a8740e7346f7', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 39, 39, 'Those who passed by blasphemed him, wagging their heads,'),
  ('022713b2-236a-57c0-a12f-bb17bf58b53c', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 40, 40, 'and saying, "You who destroy the temple, and build it in three days, save yourself! If you are the Son of God, come down from the cross!"'),
  ('dbe74235-8c81-529f-ad51-eb33760d2d43', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 41, 41, 'Likewise the chief priests also mocking, with the scribes, the Pharisees, and the elders, said,'),
  ('9dd1d72b-9049-51da-a5b6-ef79a06a5bdf', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 42, 42, '"He saved others, but he can''t save himself. If he is the King of Israel, let him come down from the cross now, and we will believe in him.'),
  ('d98300f1-3b7f-5b46-afda-9b3fac4408fe', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 43, 43, 'He trusts in God. Let God deliver him now, if he wants him; for he said, ''I am the Son of God.''"'),
  ('abe0a1d7-59af-56ce-a703-1da35932f298', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 44, 44, 'The robbers also who were crucified with him cast on him the same reproach.'),
  ('2482fe17-0d4b-56d4-a0c9-d1bb7c16ee20', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 45, 45, 'Now from the sixth hour there was darkness over all the land until the ninth hour.'),
  ('0bbaffb2-99f2-53ed-ac69-cc43200e6e17', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 46, 46, 'About the ninth hour Jesus cried with a loud voice, saying, "Eli, Eli, lima sabachthani?" That is, "My God, my God, why have you forsaken me?"'),
  ('b67f84e6-a062-537e-a8a9-bbb8d3361ea0', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 47, 47, 'Some of them who stood there, when they heard it, said, "This man is calling Elijah."'),
  ('e73863f7-27c4-5900-af6a-90b50e2ddf95', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 48, 48, 'Immediately one of them ran, and took a sponge, and filled it with vinegar, and put it on a reed, and gave him a drink.'),
  ('aa85e765-944f-580a-a4d8-6c22690acdfa', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 49, 49, 'The rest said, "Let him be. Let''s see whether Elijah comes to save him."'),
  ('55d35c67-768d-5dea-a974-fa8229bcd596', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 50, 50, 'Jesus cried again with a loud voice, and yielded up his spirit.'),
  ('4b4385c4-d45c-53aa-a819-911244e69e2e', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 51, 51, 'Behold, the veil of the temple was torn in two from the top to the bottom. The earth quaked and the rocks were split.'),
  ('7fdda7aa-52b7-5f7d-a79b-5fc87f5e7648', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 52, 52, 'The tombs were opened, and many bodies of the saints who had fallen asleep were raised;'),
  ('24ecf4cd-22b8-59a6-a462-d2fdfd87b564', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 53, 53, 'and coming out of the tombs after his resurrection, they entered into the holy city and appeared to many.'),
  ('7b76e813-3b52-5e07-aa32-d4b63f6ec385', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 54, 54, 'Now the centurion, and those who were with him watching Jesus, when they saw the earthquake, and the things that were done, feared exceedingly, saying, "Truly this was the Son of God."'),
  ('89e8f884-d8ad-5a1f-afed-fbc99f689cc0', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 55, 55, 'Many women were there watching from afar, who had followed Jesus from Galilee, serving him.'),
  ('86d8ab9f-4e4a-5cc1-a005-74a606ae48dc', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 56, 56, 'Among them were Mary Magdalene, Mary the mother of James and Joses, and the mother of the sons of Zebedee.'),
  ('b75709f2-9fef-568c-a254-5d7da51139b6', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 57, 57, 'When evening had come, a rich man from Arimathaea, named Joseph, who himself was also Jesus'' disciple came.'),
  ('ddbdee6a-90ec-5723-a712-9db2350ff1b8', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 58, 58, 'This man went to Pilate, and asked for Jesus'' body. Then Pilate commanded the body to be given up.'),
  ('0bf4494f-cbb6-51be-a370-875551f79b25', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 59, 59, 'Joseph took the body, and wrapped it in a clean linen cloth,'),
  ('469f2d3a-5c79-5529-af84-cddd802f42b0', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 60, 60, 'and laid it in his own new tomb, which he had cut out in the rock, and he rolled a great stone to the door of the tomb, and departed.'),
  ('17d8903e-a0c4-5997-a03d-3395fbe7fb0f', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 61, 61, 'Mary Magdalene was there, and the other Mary, sitting opposite the tomb.'),
  ('0ce52034-69c8-5c54-a79b-fdf5df22ce96', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 62, 62, 'Now on the next day, which was the day after the Preparation Day, the chief priests and the Pharisees were gathered together to Pilate,'),
  ('0abac2bd-8119-584d-a00d-d8c80db02a89', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 63, 63, 'saying, "Sir, we remember what that deceiver said while he was still alive: ''After three days I will rise again.'''),
  ('69e6e42a-f5a1-5d9f-af09-5c760eed7500', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 64, 64, 'Command therefore that the tomb be made secure until the third day, lest perhaps his disciples come at night and steal him away, and tell the people, ''He is risen from the dead;'' and the last deception will be worse than the first."'),
  ('ff4f730a-5d28-5b92-a2b4-579cf965a541', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 65, 65, 'Pilate said to them, "You have a guard. Go, make it as secure as you can."'),
  ('607ee5e4-60de-5843-a030-b3e6a4463a19', 'c1af9b3c-5ff5-5f5f-ac06-dc1046707c2b', NULL, 66, 66, 'So they went with the guard and made the tomb secure, sealing the stone.'),
  ('092a797c-fea6-54c7-a1ae-3d65c46be03b', '07e845ff-df7f-505e-a535-ee92e8fe56b4', NULL, 1, 1, 'Now after the Sabbath, as it began to dawn on the first day of the week, Mary Magdalene and the other Mary came to see the tomb.'),
  ('58280d29-3137-5db3-a41f-83d1ca533051', '07e845ff-df7f-505e-a535-ee92e8fe56b4', NULL, 2, 2, 'Behold, there was a great earthquake, for an angel of the Lord descended from the sky, and came and rolled away the stone from the door, and sat on it.'),
  ('2094316b-1f14-5e6c-a1c3-be9d37280df8', '07e845ff-df7f-505e-a535-ee92e8fe56b4', NULL, 3, 3, 'His appearance was like lightning, and his clothing white as snow.'),
  ('92f8a3bc-a66e-50dd-a8fe-10536fa8c7b6', '07e845ff-df7f-505e-a535-ee92e8fe56b4', NULL, 4, 4, 'For fear of him, the guards shook, and became like dead men.'),
  ('5c483321-faff-5ee9-a02f-11b35557d622', '07e845ff-df7f-505e-a535-ee92e8fe56b4', NULL, 5, 5, 'The angel answered the women, "Don''t be afraid, for I know that you seek Jesus, who has been crucified.'),
  ('b57190cb-12cc-5d5a-a9ef-fe549a66e458', '07e845ff-df7f-505e-a535-ee92e8fe56b4', NULL, 6, 6, 'He is not here, for he has risen, just like he said. Come, see the place where the Lord was lying.'),
  ('532a1408-a67b-54da-a31a-8e01539e0f0a', '07e845ff-df7f-505e-a535-ee92e8fe56b4', NULL, 7, 7, 'Go quickly and tell his disciples, ''He has risen from the dead, and behold, he goes before you into Galilee; there you will see him.'' Behold, I have told you."'),
  ('2be6df55-9fc4-5fe4-ab6f-4c1762dfa980', '07e845ff-df7f-505e-a535-ee92e8fe56b4', NULL, 8, 8, 'They departed quickly from the tomb with fear and great joy, and ran to bring his disciples word.'),
  ('6dba827c-30bc-52a3-af38-9236ad6d3b2b', '07e845ff-df7f-505e-a535-ee92e8fe56b4', NULL, 9, 9, 'As they went to tell his disciples, behold, Jesus met them, saying, "Rejoice!" They came and took hold of his feet, and worshiped him.'),
  ('b7f91b38-5e74-514f-a46e-49fc9e3da5ff', '07e845ff-df7f-505e-a535-ee92e8fe56b4', NULL, 10, 10, 'Then Jesus said to them, "Don''t be afraid. Go tell my brothers that they should go into Galilee, and there they will see me."'),
  ('5250c2e7-cd78-500b-a148-147d3176f6ea', '07e845ff-df7f-505e-a535-ee92e8fe56b4', NULL, 11, 11, 'Now while they were going, behold, some of the guards came into the city, and told the chief priests all the things that had happened.'),
  ('a4c8d5bc-6445-5882-acfb-e3d6e1a0bdd0', '07e845ff-df7f-505e-a535-ee92e8fe56b4', NULL, 12, 12, 'When they were assembled with the elders, and had taken counsel, they gave a large amount of silver to the soldiers,'),
  ('b8659db3-290b-51a9-a924-f17f430971aa', '07e845ff-df7f-505e-a535-ee92e8fe56b4', NULL, 13, 13, 'saying, "Say that his disciples came by night, and stole him away while we slept.'),
  ('a2157714-8e58-578a-a7fa-df445734ded4', '07e845ff-df7f-505e-a535-ee92e8fe56b4', NULL, 14, 14, 'If this comes to the governor''s ears, we will persuade him and make you free of worry."'),
  ('96980155-268a-5d4f-a6cb-f413d5688d35', '07e845ff-df7f-505e-a535-ee92e8fe56b4', NULL, 15, 15, 'So they took the money and did as they were told. This saying was spread abroad among the Jews, and continues until this day.'),
  ('b3136920-dbf2-56c9-ac1e-3481ece16f6f', '07e845ff-df7f-505e-a535-ee92e8fe56b4', NULL, 16, 16, 'But the eleven disciples went into Galilee, to the mountain where Jesus had sent them.'),
  ('27187b38-7dc4-5e5b-aaae-3454c8f45929', '07e845ff-df7f-505e-a535-ee92e8fe56b4', NULL, 17, 17, 'When they saw him, they bowed down to him, but some doubted.'),
  ('39d7837f-138c-5989-a9af-4acddb51a0bf', '07e845ff-df7f-505e-a535-ee92e8fe56b4', NULL, 18, 18, 'Jesus came to them and spoke to them, saying, "All authority has been given to me in heaven and on earth.'),
  ('f1ada36e-43d5-5dac-a784-eb91b81707c6', '07e845ff-df7f-505e-a535-ee92e8fe56b4', NULL, 19, 19, 'Go, and make disciples of all nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit,'),
  ('26bfd697-6145-5213-ab2e-89b358f414d7', '07e845ff-df7f-505e-a535-ee92e8fe56b4', NULL, 20, 20, 'teaching them to observe all things that I commanded you. Behold, I am with you always, even to the end of the age." Amen.'),
  ('9762456e-b750-5f14-a4bd-00ad814eeb81', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 1, 1, 'The beginning of the Good News of Jesus Christ, the Son of God.'),
  ('6be1fcca-721e-5ed7-a077-270d7ab84a26', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 2, 2, 'As it is written in the prophets, "Behold, I send my messenger before your face, who will prepare your way before you.'),
  ('9fc4e48e-2749-5c19-a9fb-adaec4aa80a9', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 3, 3, 'The voice of one crying in the wilderness, ''Make ready the way of the Lord! Make his paths straight!''"'),
  ('24a4c51d-294c-531a-ac73-c8f6b9b108d1', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 4, 4, 'John came baptizing in the wilderness and preaching the baptism of repentance for forgiveness of sins.'),
  ('e5fbda29-1d75-5630-a524-2bc5181be7a4', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 5, 5, 'All the country of Judea and all those of Jerusalem went out to him. They were baptized by him in the Jordan river, confessing their sins.'),
  ('94b3e32f-3c71-59b9-a195-d7ab025c825e', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 6, 6, 'John was clothed with camel''s hair and a leather belt around his waist. He ate locusts and wild honey.'),
  ('b3ddc00b-78fd-56e3-a7cf-b882a8308b9d', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 7, 7, 'He preached, saying, "After me comes he who is mightier than I, the thong of whose sandals I am not worthy to stoop down and loosen.'),
  ('39845ba4-3550-5e7d-adaa-3e2da83828f7', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 8, 8, 'I baptized you in water, but he will baptize you in the Holy Spirit."'),
  ('2517131c-c9d3-5ba8-acc8-111179505378', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 9, 9, 'It happened in those days, that Jesus came from Nazareth of Galilee, and was baptized by John in the Jordan.'),
  ('64ddb5a2-d174-51dc-a62c-2c5c53244eab', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 10, 10, 'Immediately coming up from the water, he saw the heavens parting, and the Spirit descending on him like a dove.'),
  ('c7580d49-bee7-539e-a62a-a6068e3ee36b', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 11, 11, 'A voice came out of the sky, "You are my beloved Son, in whom I am well pleased."'),
  ('0fb4f154-bd20-59be-aff9-4637e15167d4', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 12, 12, 'Immediately the Spirit drove him out into the wilderness.'),
  ('9ab09af8-360a-5198-a4e5-2452d21e2ebc', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 13, 13, 'He was there in the wilderness forty days tempted by Satan. He was with the wild animals; and the angels were serving him.'),
  ('87bc68b8-6d79-5602-a1db-9c87167c78da', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 14, 14, 'Now after John was taken into custody, Jesus came into Galilee, preaching the Good News of the Kingdom of God,'),
  ('eb0da47b-18d8-59c1-a20b-44b852225dd6', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 15, 15, 'and saying, "The time is fulfilled, and the Kingdom of God is at hand! Repent, and believe in the Good News."'),
  ('deb847aa-d298-5399-a3ad-80b4fbf753d1', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 16, 16, 'Passing along by the sea of Galilee, he saw Simon and Andrew the brother of Simon casting a net into the sea, for they were fishermen.'),
  ('1bb23196-80ae-5185-af58-607ee5e26960', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 17, 17, 'Jesus said to them, "Come after me, and I will make you into fishers for men."'),
  ('83891c77-b51b-5a23-a7a7-7c14f165dc6f', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 18, 18, 'Immediately they left their nets, and followed him.'),
  ('f2efb94e-b2e7-5bbc-ad7f-57723e324ba6', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 19, 19, 'Going on a little further from there, he saw James the son of Zebedee, and John, his brother, who were also in the boat mending the nets.'),
  ('c30cc3f3-0811-5396-af34-0896273cdf2d', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 20, 20, 'Immediately he called them, and they left their father, Zebedee, in the boat with the hired servants, and went after him.'),
  ('53330c71-7d25-5e68-aff0-6172f784cbb5', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 21, 21, 'They went into Capernaum, and immediately on the Sabbath day he entered into the synagogue and taught.'),
  ('effa9a05-de31-5070-a20b-563476cfbc7e', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 22, 22, 'They were astonished at his teaching, for he taught them as having authority, and not as the scribes.'),
  ('55566502-bdad-5d7b-a6de-b2cc84a625f4', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 23, 23, 'Immediately there was in their synagogue a man with an unclean spirit, and he cried out,'),
  ('cee725e7-f56f-5a8c-ad34-fe96436e732a', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 24, 24, 'saying, "Ha! What do we have to do with you, Jesus, you Nazarene? Have you come to destroy us? I know you who you are: the Holy One of God!"'),
  ('0a14b20f-7fa8-55ba-a3de-d93cdd028292', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 25, 25, 'Jesus rebuked him, saying, "Be quiet, and come out of him!"'),
  ('0af0b9c8-b6c9-51be-a3c4-2801f782c99c', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 26, 26, 'The unclean spirit, convulsing him and crying with a loud voice, came out of him.'),
  ('345e8def-f25e-5fe8-a056-47b4266f21ff', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 27, 27, 'They were all amazed, so that they questioned among themselves, saying, "What is this? A new teaching? For with authority he commands even the unclean spirits, and they obey him!"'),
  ('f8ff06cc-33dc-5d44-a305-0209d54f7135', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 28, 28, 'The report of him went out immediately everywhere into all the region of Galilee and its surrounding area.'),
  ('cca4b24f-43bf-582b-ab87-e02d98602ea5', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 29, 29, 'Immediately, when they had come out of the synagogue, they came into the house of Simon and Andrew, with James and John.'),
  ('1f5cfa07-bfa2-53ff-a2e1-221668aceb3c', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 30, 30, 'Now Simon''s wife''s mother lay sick with a fever, and immediately they told him about her.'),
  ('37744587-6cd1-53c6-a7eb-1f5a6b62cd7d', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 31, 31, 'He came and took her by the hand, and raised her up. The fever left her, and she served them.'),
  ('9e874fcb-040f-5aaf-a4fc-27134a908bfa', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 32, 32, 'At evening, when the sun had set, they brought to him all who were sick, and those who were possessed by demons.'),
  ('48d2bd66-75d4-5638-a5a0-7dff868820b1', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 33, 33, 'All the city was gathered together at the door.'),
  ('5f706927-5b3d-5db9-aa8a-afd2ea2a9460', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 34, 34, 'He healed many who were sick with various diseases, and cast out many demons. He didn''t allow the demons to speak, because they knew him.'),
  ('368bff0a-78e2-551a-a20b-341aaf049e89', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 35, 35, 'Early in the morning, while it was still dark, he rose up and went out, and departed into a deserted place, and prayed there.'),
  ('06164cf7-42a8-5a58-afd2-6c31ce6e3704', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 36, 36, 'Simon and those who were with him followed after him;'),
  ('014e269e-e013-56ac-a1b8-275e814c54f9', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 37, 37, 'and they found him, and told him, "Everyone is looking for you."'),
  ('e500c6fb-580d-5670-ac4a-8d93353a87e0', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 38, 38, 'He said to them, "Let''s go elsewhere into the next towns, that I may preach there also, because I came out for this reason."'),
  ('950ac75a-e4b3-5a5b-ac6d-22dceaed6a0e', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 39, 39, 'He went into their synagogues throughout all Galilee, preaching and casting out demons.'),
  ('3cd15670-174d-5e6a-affe-7b07b40b9444', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 40, 40, 'A leper came to him, begging him, kneeling down to him, and saying to him, "If you want to, you can make me clean."'),
  ('76f74d57-d8c8-56a9-a484-f61851541b37', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 41, 41, 'Being moved with compassion, he stretched out his hand, and touched him, and said to him, "I want to. Be made clean."'),
  ('a9cbc04f-a4d4-58eb-a11f-3871fe2bc681', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 42, 42, 'When he had said this, immediately the leprosy departed from him, and he was made clean.'),
  ('7436511b-b88e-53d8-ac97-39942f6f7ec4', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 43, 43, 'He strictly warned him, and immediately sent him out,'),
  ('1efec688-0f02-546e-a0f8-2d95747964ef', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 44, 44, 'and said to him, "See you say nothing to anybody, but go show yourself to the priest, and offer for your cleansing the things which Moses commanded, for a testimony to them."'),
  ('482463a2-cddb-5c05-aa2e-c6ba9d6cf2ae', '847e9dd6-422a-5784-a04e-92533dbb1dee', NULL, 45, 45, 'But he went out, and began to proclaim it much, and to spread about the matter, so that Jesus could no more openly enter into a city, but was outside in desert places: and they came to him from everywhere.'),
  ('e2eaa4a0-70d2-5fa5-a158-2b4b63d05809', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 1, 1, 'When he entered again into Capernaum after some days, it was heard that he was in the house.'),
  ('90e2bb3e-7f8d-55c2-ac47-282f971029e5', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 2, 2, 'Immediately many were gathered together, so that there was no more room, not even around the door; and he spoke the word to them.'),
  ('cab22627-d8ff-5519-a26c-1f098e16b808', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 3, 3, 'Four people came, carrying a paralytic to him.'),
  ('05a5ee98-22c1-5987-a92d-36b54bafeb18', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 4, 4, 'When they could not come near to him for the crowd, they removed the roof where he was. When they had broken it up, they let down the mat that the paralytic was lying on.'),
  ('740e824f-88f6-5e3b-ac85-2fd34ef9ff6e', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 5, 5, 'Jesus, seeing their faith, said to the paralytic, "Son, your sins are forgiven you."'),
  ('9c65f611-f5d1-5289-a462-d463ca7a7214', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 6, 6, 'But there were some of the scribes sitting there, and reasoning in their hearts,'),
  ('d7646af4-d6f5-5ed6-a1b8-b679b3f8dc9e', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 7, 7, '"Why does this man speak blasphemies like that? Who can forgive sins but God alone?"'),
  ('4cc6f403-e7ff-5438-a95d-1c2f1deb9ca5', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 8, 8, 'Immediately Jesus, perceiving in his spirit that they so reasoned within themselves, said to them, "Why do you reason these things in your hearts?'),
  ('715b3596-3228-5240-a2ee-df4ed320ac70', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 9, 9, 'Which is easier, to tell the paralytic, ''Your sins are forgiven;'' or to say, ''Arise, and take up your bed, and walk?'''),
  ('8e9a4ab4-0c7b-53f4-a1fe-3ed64413cf32', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 10, 10, 'But that you may know that the Son of Man has authority on earth to forgive sins"--he said to the paralytic--'),
  ('cb841093-6a86-59e8-aeda-27446437c894', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 11, 11, '"I tell you, arise, take up your mat, and go to your house."'),
  ('2f1c8d48-e035-598b-a697-7a3c638775b9', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 12, 12, 'He arose, and immediately took up the mat, and went out in front of them all; so that they were all amazed, and glorified God, saying, "We never saw anything like this!"'),
  ('a4651bc3-7a60-5fdb-ad74-91082c94627a', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 13, 13, 'He went out again by the seaside. All the multitude came to him, and he taught them.'),
  ('fabb6e50-d291-549a-ae07-0f199031c7d5', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 14, 14, 'As he passed by, he saw Levi, the son of Alphaeus, sitting at the tax office, and he said to him, "Follow me." And he arose and followed him.'),
  ('cab12707-2516-520e-a95e-7f08b30f8f0a', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 15, 15, 'It happened, that he was reclining at the table in his house, and many tax collectors and sinners sat down with Jesus and his disciples, for there were many, and they followed him.'),
  ('ee502ed6-ab57-5588-a034-4ae99930438d', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 16, 16, 'The scribes and the Pharisees, when they saw that he was eating with the sinners and tax collectors, said to his disciples, "Why is it that he eats and drinks with tax collectors and sinners?"'),
  ('b93b970b-5087-59e0-a9e0-32b278e8e609', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 17, 17, 'When Jesus heard it, he said to them, "Those who are healthy have no need for a physician, but those who are sick. I came not to call the righteous, but sinners to repentance."'),
  ('5282615e-cd7d-5bdf-a4b5-34f9e7fde806', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 18, 18, 'John''s disciples and the Pharisees were fasting, and they came and asked him, "Why do John''s disciples and the disciples of the Pharisees fast, but your disciples don''t fast?"'),
  ('1a160ceb-dc49-56f4-a6be-aec90676e8b4', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 19, 19, 'Jesus said to them, "Can the groomsmen fast while the bridegroom is with them? As long as they have the bridegroom with them, they can''t fast.'),
  ('65ddd426-7e19-56cc-a618-68b6db43afd9', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 20, 20, 'But the days will come when the bridegroom will be taken away from them, and then will they fast in that day.'),
  ('50eafac5-7d0a-50f3-af4f-86052c2dbf77', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 21, 21, 'No one sews a piece of unshrunk cloth on an old garment, or else the patch shrinks and the new tears away from the old, and a worse hole is made.'),
  ('27730107-1c77-5fb6-aac4-fd693722d33c', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 22, 22, 'No one puts new wine into old wineskins, or else the new wine will burst the skins, and the wine pours out, and the skins will be destroyed; but they put new wine into fresh wineskins."'),
  ('090215f3-e8ab-57da-a5c5-d8a340d75825', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 23, 23, 'It happened that he was going on the Sabbath day through the grain fields, and his disciples began, as they went, to pluck the ears of grain.'),
  ('18232415-9a0e-5e81-a308-85d6b6c292a5', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 24, 24, 'The Pharisees said to him, "Behold, why do they do that which is not lawful on the Sabbath day?"'),
  ('3e4e2096-8591-5da9-af9b-4b5e5a6bba33', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 25, 25, 'He said to them, "Did you never read what David did, when he had need, and was hungry--he, and those who were with him?'),
  ('42fd154f-9947-51d5-a009-ebea1ae56f93', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 26, 26, 'How he entered into the house of God when Abiathar was high priest, and ate the show bread, which is not lawful to eat except for the priests, and gave also to those who were with him?"'),
  ('7d99df49-36c6-5e08-a9e5-70db730df966', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 27, 27, 'He said to them, "The Sabbath was made for man, not man for the Sabbath.'),
  ('e23f9946-04af-5aa2-ad76-ca36e2be6d3c', '9f8dc921-4ab4-5a44-a5d7-673f4093a5ed', NULL, 28, 28, 'Therefore the Son of Man is lord even of the Sabbath."'),
  ('671d1a40-be0f-5121-aad1-7e5da76d9820', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 1, 1, 'He entered again into the synagogue, and there was a man there who had his hand withered.'),
  ('d4dd63a0-43e3-57c6-ad53-8f0a4629db03', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 2, 2, 'They watched him, whether he would heal him on the Sabbath day, that they might accuse him.'),
  ('e94e76a8-5434-5810-a05b-e0f4cd0772e2', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 3, 3, 'He said to the man who had his hand withered, "Stand up."'),
  ('baeae106-8cc4-5177-a354-30a79bb6ee11', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 4, 4, 'He said to them, "Is it lawful on the Sabbath day to do good, or to do harm? To save a life, or to kill?" But they were silent.'),
  ('45ed2b87-8a81-5c14-aef6-8530f17507af', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 5, 5, 'When he had looked around at them with anger, being grieved at the hardening of their hearts, he said to the man, "Stretch out your hand." He stretched it out, and his hand was restored as healthy as the other.'),
  ('a891f9ab-8344-57c9-ae04-a070cb7a9800', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 6, 6, 'The Pharisees went out, and immediately conspired with the Herodians against him, how they might destroy him.'),
  ('0f59e254-9bbb-5ae8-a476-4a07e94db122', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 7, 7, 'Jesus withdrew to the sea with his disciples, and a great multitude followed him from Galilee, from Judea,'),
  ('84311cd5-304a-5caf-af03-547da5657a53', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 8, 8, 'from Jerusalem, from Idumaea, beyond the Jordan, and those from around Tyre and Sidon. A great multitude, hearing what great things he did, came to him.'),
  ('2957044b-29b1-5faf-a42d-4f4471a8e3fe', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 9, 9, 'He spoke to his disciples that a little boat should stay near him because of the crowd, so that they wouldn''t press on him.'),
  ('a82e44b7-c83c-5509-a36f-7faa80ebe5e9', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 10, 10, 'For he had healed many, so that as many as had diseases pressed on him that they might touch him.'),
  ('bec4f5ac-3e2b-57e4-ae69-ea03528dac28', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 11, 11, 'The unclean spirits, whenever they saw him, fell down before him, and cried, "You are the Son of God!"'),
  ('f505fb35-7e28-5621-ac3e-bc8d1555164a', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 12, 12, 'He sternly warned them that they should not make him known.'),
  ('efc92571-10f4-586d-a7c5-01f98e26d7ac', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 13, 13, 'He went up into the mountain, and called to himself those whom he wanted, and they went to him.'),
  ('9fde01be-3e99-5109-aa26-f1cc7bcfe783', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 14, 14, 'He appointed twelve, that they might be with him, and that he might send them out to preach,'),
  ('914b33d9-afe1-56b6-a30e-518d0b0d9803', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 15, 15, 'and to have authority to heal sicknesses and to cast out demons:'),
  ('14cf6bee-aa6d-544c-ad85-0353a02d70ab', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 16, 16, 'Simon, to whom he gave the name Peter;'),
  ('7e6842fa-b88d-5419-abf5-c792c6799f8f', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 17, 17, 'James the son of Zebedee; John, the brother of James, and he surnamed them Boanerges, which means, Sons of Thunder;'),
  ('8c7e6cce-7b63-5d41-aa2d-0a7da4d7ad77', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 18, 18, 'Andrew; Philip; Bartholomew; Matthew; Thomas; James, the son of Alphaeus; Thaddaeus; Simon the Zealot;'),
  ('4ad45c18-5629-5dec-ace8-9ade26514381', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 19, 19, 'and Judas Iscariot, who also betrayed him. He came into a house.'),
  ('1662a272-4784-57f8-ab1c-9dfdb868b472', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 20, 20, 'The multitude came together again, so that they could not so much as eat bread.'),
  ('74fc2ff5-41d1-5fbf-ad33-e9b8e6452e5c', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 21, 21, 'When his friends heard it, they went out to seize him: for they said, "He is insane."'),
  ('311a959d-cd95-5f36-a7e3-218206c4120b', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 22, 22, 'The scribes who came down from Jerusalem said, "He has Beelzebul," and, "By the prince of the demons he casts out the demons."'),
  ('20260b14-6e4f-5de0-a5fc-43078586c032', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 23, 23, 'He summoned them, and said to them in parables, "How can Satan cast out Satan?'),
  ('0976f2c3-c7bb-5273-aaa3-726cd0649f4f', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 24, 24, 'If a kingdom is divided against itself, that kingdom cannot stand.'),
  ('9a0dd37e-a2e4-5fd6-abe9-1a2ae45a3c5d', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 25, 25, 'If a house is divided against itself, that house cannot stand.'),
  ('9f6a28f4-8763-50d0-ac1e-db38119502db', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 26, 26, 'If Satan has risen up against himself, and is divided, he can''t stand, but has an end.'),
  ('a337f60a-d644-5877-a283-04a936cb8e2a', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 27, 27, 'But no one can enter into the house of the strong man to plunder, unless he first binds the strong man; and then he will plunder his house.'),
  ('8d8f1ec4-2b37-522a-ad57-550415ec52da', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 28, 28, 'Most certainly I tell you, all sins of the descendants of man will be forgiven, including their blasphemies with which they may blaspheme;'),
  ('c0023c2e-95af-5f01-a534-2fc3787a4763', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 29, 29, 'but whoever may blaspheme against the Holy Spirit never has forgiveness, but is guilty of an eternal sin"'),
  ('6426cc32-ef4e-5740-a203-b5e6d68e5530', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 30, 30, '--because they said, "He has an unclean spirit."'),
  ('384e4b3d-4e30-595c-a7a1-b532f1de28a4', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 31, 31, 'His mother and his brothers came, and standing outside, they sent to him, calling him.'),
  ('5ad3b1dd-5ed0-5d0e-aad0-cb8cd2573c8c', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 32, 32, 'A multitude was sitting around him, and they told him, "Behold, your mother, your brothers, and your sisters are outside looking for you."'),
  ('66835b79-8e7a-5192-aed4-d3667a63ab34', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 33, 33, 'He answered them, "Who are my mother and my brothers?"'),
  ('fcd77bce-5061-51f2-a788-448972ad022e', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 34, 34, 'Looking around at those who sat around him, he said, "Behold, my mother and my brothers!'),
  ('dffeb0c5-c285-5d28-ae36-3ec23c87caf4', 'cb54b95d-ceaf-59a4-af3f-6b53f49f1d08', NULL, 35, 35, 'For whoever does the will of God, the same is my brother, and my sister, and mother."'),
  ('978515b8-e3ae-5adc-ac6e-3682c64caa4a', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 1, 1, 'Again he began to teach by the seaside. A great multitude was gathered to him, so that he entered into a boat in the sea, and sat down. All the multitude were on the land by the sea.'),
  ('2b757550-a5f6-50be-a4f7-1dfa6e1e2ff4', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 2, 2, 'He taught them many things in parables, and told them in his teaching,'),
  ('8f3fd2ef-e40e-5c9a-ab2f-20b1546b5efb', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 3, 3, '"Listen! Behold, the farmer went out to sow,'),
  ('a9c5674c-e8d1-5d9d-ab8f-57eacfa8d1d6', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 4, 4, 'and it happened, as he sowed, some seed fell by the road, and the birds came and devoured it.'),
  ('f2110a76-9f5a-5f3b-a819-4b1912577495', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 5, 5, 'Others fell on the rocky ground, where it had little soil, and immediately it sprang up, because it had no depth of soil.'),
  ('7d0ff2fd-580a-51d8-a6c2-cd47e845f993', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 6, 6, 'When the sun had risen, it was scorched; and because it had no root, it withered away.'),
  ('93407268-418f-5b4e-a663-1fa738e4287f', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 7, 7, 'Others fell among the thorns, and the thorns grew up, and choked it, and it yielded no fruit.'),
  ('3b9419c8-c46e-559e-add4-0069dd1e7509', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 8, 8, 'Others fell into the good ground, and yielded fruit, growing up and increasing. Some brought forth thirty times, some sixty times, and some one hundred times as much."'),
  ('ea5159fb-125f-592a-aa7c-91f804e8f0b0', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 9, 9, 'He said, "Whoever has ears to hear, let him hear."'),
  ('611ba712-eb59-5165-a842-df5e177548f4', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 10, 10, 'When he was alone, those who were around him with the twelve asked him about the parables.'),
  ('9286c8bf-c863-53d5-ad78-1455bc2d5a41', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 11, 11, 'He said to them, "To you is given the mystery of the Kingdom of God, but to those who are outside, all things are done in parables,'),
  ('fff634a5-4b2c-5c95-adbf-dd2ca15d89e9', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 12, 12, 'that ''seeing they may see, and not perceive; and hearing they may hear, and not understand; lest perhaps they should turn again, and their sins should be forgiven them.''"'),
  ('5d00b2f0-ed63-521c-ae84-a1c813a815ba', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 13, 13, 'He said to them, "Don''t you understand this parable? How will you understand all of the parables?'),
  ('77bc3754-ae3c-54bc-ac3d-0e939885baae', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 14, 14, 'The farmer sows the word.'),
  ('65f0f466-c66a-5e25-a948-41135298a23b', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 15, 15, 'The ones by the road are the ones where the word is sown; and when they have heard, immediately Satan comes, and takes away the word which has been sown in them.'),
  ('992551e5-fcc3-52de-aa6b-8b154854967b', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 16, 16, 'These in the same way are those who are sown on the rocky places, who, when they have heard the word, immediately receive it with joy.'),
  ('470d665f-bc91-5fac-a920-fc5ac513d404', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 17, 17, 'They have no root in themselves, but are short-lived. When oppression or persecution arises because of the word, immediately they stumble.'),
  ('ef45efd9-494b-5eb5-adf8-29cb0d601ca0', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 18, 18, 'Others are those who are sown among the thorns. These are those who have heard the word,'),
  ('278ccba1-fc7d-5d77-ac70-499d70c2e6d5', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 19, 19, 'and the cares of this age, and the deceitfulness of riches, and the lusts of other things entering in choke the word, and it becomes unfruitful.'),
  ('dc4ba5bd-34ff-5335-ac5d-68cbb12b3f8a', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 20, 20, 'Those which were sown on the good ground are those who hear the word, and accept it, and bear fruit, some thirty times, some sixty times, and some one hundred times."'),
  ('14b9cc25-580f-5f2c-acb3-b651c2238055', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 21, 21, 'He said to them, "Is the lamp brought to be put under a basket or under a bed? Isn''t it put on a stand?'),
  ('94156883-40a3-51c2-a72e-678a12afa4a1', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 22, 22, 'For there is nothing hidden, except that it should be made known; neither was anything made secret, but that it should come to light.'),
  ('1081e289-5c1e-50a5-af57-15cb328cc371', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 23, 23, 'If any man has ears to hear, let him hear."'),
  ('09a25bf6-52f5-53ab-a314-82d5d1d92de2', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 24, 24, 'He said to them, "Take heed what you hear. With whatever measure you measure, it will be measured to you, and more will be given to you who hear.'),
  ('627df494-6b6e-549c-ada8-ee0b7fc550e4', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 25, 25, 'For whoever has, to him will more be given, and he who doesn''t have, even that which he has will be taken away from him."'),
  ('2e4e7dfe-5c8b-5d10-aec3-dea82e2432e0', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 26, 26, 'He said, "The Kingdom of God is as if a man should cast seed on the earth,'),
  ('0c8abed2-a293-5d65-aa54-b4a41d1f66db', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 27, 27, 'and should sleep and rise night and day, and the seed should spring up and grow, he doesn''t know how.'),
  ('7190afb1-f1ac-5357-affa-ba73d552bf14', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 28, 28, 'For the earth bears fruit: first the blade, then the ear, then the full grain in the ear.'),
  ('f872352c-10c4-598b-abd8-c3925565ae37', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 29, 29, 'But when the fruit is ripe, immediately he puts forth the sickle, because the harvest has come."'),
  ('0158e7bb-1242-51af-ab0a-a253131dab78', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 30, 30, 'He said, "How will we liken the Kingdom of God? Or with what parable will we illustrate it?'),
  ('1172ca7d-dbc4-5d08-a918-b6af630e781f', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 31, 31, 'It''s like a grain of mustard seed, which, when it is sown in the earth, though it is less than all the seeds that are on the earth,'),
  ('448864cb-df3b-55e1-a34f-1655a53b6427', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 32, 32, 'yet when it is sown, grows up, and becomes greater than all the herbs, and puts out great branches, so that the birds of the sky can lodge under its shadow."'),
  ('b659c0ae-7973-5a28-aea4-1865a76bc8cc', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 33, 33, 'With many such parables he spoke the word to them, as they were able to hear it.'),
  ('07c0eab5-4d18-5e0f-a99d-1a81f2148b53', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 34, 34, 'Without a parable he didn''t speak to them; but privately to his own disciples he explained everything.'),
  ('33d0e5ac-eaac-5538-a002-85e5a9904b88', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 35, 35, 'On that day, when evening had come, he said to them, "Let''s go over to the other side."'),
  ('3784328b-7e3f-55ef-a95c-59d1c9a73e0d', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 36, 36, 'Leaving the multitude, they took him with them, even as he was, in the boat. Other small boats were also with him.'),
  ('d7c34f4d-d8cc-5346-aafe-29e7b7a969a9', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 37, 37, 'A big wind storm arose, and the waves beat into the boat, so much that the boat was already filled.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('55027595-828b-534d-a8fc-6086bf3845a6', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 38, 38, 'He himself was in the stern, asleep on the cushion, and they woke him up, and told him, "Teacher, don''t you care that we are dying?"'),
  ('5975ef42-9b7f-5575-ab18-593b3e4b87c8', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 39, 39, 'He awoke, and rebuked the wind, and said to the sea, "Peace! Be still!" The wind ceased, and there was a great calm.'),
  ('dae29520-84b3-5d75-aed5-cd0db4920f16', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 40, 40, 'He said to them, "Why are you so afraid? How is it that you have no faith?"'),
  ('979b8bcf-1bf3-52b0-a9ca-a7ee8a05ed5a', '90e88140-27b5-514c-a340-a5c7a63e5eef', NULL, 41, 41, 'They were greatly afraid, and said to one another, "Who then is this, that even the wind and the sea obey him?"'),
  ('2d5d8493-325f-514d-ad9f-5fde5725b049', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 1, 1, 'They came to the other side of the sea, into the country of the Gadarenes.'),
  ('5fd339d2-2b43-5856-a972-9981e3c8b25f', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 2, 2, 'When he had come out of the boat, immediately a man with an unclean spirit met him out of the tombs.'),
  ('511ec5b3-4b40-5f36-a0a0-ca2a8a621514', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 3, 3, 'He lived in the tombs. Nobody could bind him any more, not even with chains,'),
  ('e710e8ec-f33a-5f1d-aaa5-ab53c6e81558', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 4, 4, 'because he had been often bound with fetters and chains, and the chains had been torn apart by him, and the fetters broken in pieces. Nobody had the strength to tame him.'),
  ('d8e7c0b5-3c38-570e-a17d-faa8fd433369', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 5, 5, 'Always, night and day, in the tombs and in the mountains, he was crying out, and cutting himself with stones.'),
  ('b954f5f8-58f7-5391-a580-f7416f947d57', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 6, 6, 'When he saw Jesus from afar, he ran and bowed down to him,'),
  ('d8c39da0-1c21-53a8-a0bb-0d38cdfa290f', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 7, 7, 'and crying out with a loud voice, he said, "What have I to do with you, Jesus, you Son of the Most High God? I adjure you by God, don''t torment me."'),
  ('e0a95224-a7db-51aa-a59b-db29aa5fd2d8', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 8, 8, 'For he said to him, "Come out of the man, you unclean spirit!"'),
  ('d6986a7d-fb78-5dba-a8bb-54de065e8cbb', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 9, 9, 'He asked him, "What is your name?" He said to him, "My name is Legion, for we are many."'),
  ('da1d3d80-8036-5e46-a8b8-2540f2bf7473', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 10, 10, 'He begged him much that he would not send them away out of the country.'),
  ('5d4277c8-cb0d-5d71-acd1-d3323fe0a091', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 11, 11, 'Now on the mountainside there was a great herd of pigs feeding.'),
  ('dd3eff41-d23e-5243-a338-a91e46818f11', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 12, 12, 'All the demons begged him, saying, "Send us into the pigs, that we may enter into them."'),
  ('cee2d363-e240-54be-a19f-248a37c7c08c', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 13, 13, 'At once Jesus gave them permission. The unclean spirits came out and entered into the pigs. The herd of about two thousand rushed down the steep bank into the sea, and they were drowned in the sea.'),
  ('5107e1c2-e0f2-56e6-a08e-2433367f69d2', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 14, 14, 'Those who fed them fled, and told it in the city and in the country. The people came to see what it was that had happened.'),
  ('1e33aefd-85eb-51ea-a35a-5e61312ae197', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 15, 15, 'They came to Jesus, and saw him who had been possessed by demons sitting, clothed, and in his right mind, even him who had the legion; and they were afraid.'),
  ('f921dd3b-5a58-5f72-a299-8f3daab95cfa', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 16, 16, 'Those who saw it declared to them how it happened to him who was possessed by demons, and about the pigs.'),
  ('861bc748-53dc-52b7-ac0f-5b4d4ecbbc0f', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 17, 17, 'They began to beg him to depart from their region.'),
  ('04948ed2-30d4-57fb-a58f-a0cc91f245cd', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 18, 18, 'As he was entering into the boat, he who had been possessed by demons begged him that he might be with him.'),
  ('73ad6861-507c-51d0-a008-dcebde4eaf7c', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 19, 19, 'He didn''t allow him, but said to him, "Go to your house, to your friends, and tell them what great things the Lord has done for you, and how he had mercy on you."'),
  ('d09bc5b1-aeb2-5753-abb2-bb7b7c8abb0f', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 20, 20, 'He went his way, and began to proclaim in Decapolis how Jesus had done great things for him, and everyone marveled.'),
  ('bf7c2611-d289-52fe-a20a-3762d6e52a6d', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 21, 21, 'When Jesus had crossed back over in the boat to the other side, a great multitude was gathered to him; and he was by the sea.'),
  ('3b5d7d96-ef3c-5434-a43d-1bd0d1a43127', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 22, 22, 'Behold, one of the rulers of the synagogue, Jairus by name, came; and seeing him, he fell at his feet,'),
  ('7ab16e25-7860-5848-a5f1-54da763f3430', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 23, 23, 'and begged him much, saying, "My little daughter is at the point of death. Please come and lay your hands on her, that she may be made healthy, and live."'),
  ('811c419e-bb94-5809-a4e1-fd1c9792d670', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 24, 24, 'He went with him, and a great multitude followed him, and they pressed upon him on all sides.'),
  ('c7eed656-3363-57b2-a630-b1991033286c', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 25, 25, 'A certain woman, who had an issue of blood for twelve years,'),
  ('f5177210-4155-5cc9-a916-cf5281f659d2', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 26, 26, 'and had suffered many things by many physicians, and had spent all that she had, and was no better, but rather grew worse,'),
  ('7633e475-d079-5b45-acbc-4fc456f90a4d', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 27, 27, 'having heard the things concerning Jesus, came up behind him in the crowd, and touched his clothes.'),
  ('e38c3b9e-77b6-5c6b-af2d-5d964a9d1055', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 28, 28, 'For she said, "If I just touch his clothes, I will be made well."'),
  ('e5b95250-f3f4-5c6d-a0a0-ffb97eca7398', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 29, 29, 'Immediately the flow of her blood was dried up, and she felt in her body that she was healed of her affliction.'),
  ('b12430df-d597-58f1-adcf-f1121047cce2', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 30, 30, 'Immediately Jesus, perceiving in himself that the power had gone out from him, turned around in the crowd, and asked, "Who touched my clothes?"'),
  ('21cf96db-397c-537f-a8c0-adde5255a9fd', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 31, 31, 'His disciples said to him, "You see the multitude pressing against you, and you say, ''Who touched me?''"'),
  ('4457f162-3ab8-5e86-ac8e-2ed526f58c35', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 32, 32, 'He looked around to see her who had done this thing.'),
  ('d8a53bef-3658-5bb8-a681-b5e1da271d40', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 33, 33, 'But the woman, fearing and trembling, knowing what had been done to her, came and fell down before him, and told him all the truth.'),
  ('49f00b6e-20e7-56f5-a304-6d640632648b', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 34, 34, 'He said to her, "Daughter, your faith has made you well. Go in peace, and be cured of your disease."'),
  ('b8beb38a-a214-56b9-ad25-4cf562a6b18b', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 35, 35, 'While he was still speaking, people came from the synagogue ruler''s house saying, "Your daughter is dead. Why bother the Teacher any more?"'),
  ('1230d0ba-557b-5a87-a381-d76fd66efd63', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 36, 36, 'But Jesus, when he heard the message spoken, immediately said to the ruler of the synagogue, "Don''t be afraid, only believe."'),
  ('38283a52-2dda-5d81-a7b0-934330e3261a', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 37, 37, 'He allowed no one to follow him, except Peter, James, and John the brother of James.'),
  ('dd6853e3-22c5-5549-ac78-911e4797108b', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 38, 38, 'He came to the synagogue ruler''s house, and he saw an uproar, weeping, and great wailing.'),
  ('0ff7a8c8-0694-5d43-abd9-014b26034487', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 39, 39, 'When he had entered in, he said to them, "Why do you make an uproar and weep? The child is not dead, but is asleep."'),
  ('f8f39c4b-063d-595d-aab2-b638e0efffbc', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 40, 40, 'They ridiculed him. But he, having put them all out, took the father of the child, her mother, and those who were with him, and went in where the child was lying.'),
  ('6cfa946d-e6ae-5d97-a0d4-3090688adff9', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 41, 41, 'Taking the child by the hand, he said to her, "Talitha cumi!" which means, being interpreted, "Girl, I tell you, get up!"'),
  ('94950788-c023-53a3-a7e9-761cc074c5a2', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 42, 42, 'Immediately the girl rose up and walked, for she was twelve years old. They were amazed with great amazement.'),
  ('6121133b-aed3-5d40-a9ea-d74cebf781b1', 'fdc1e394-4df0-5805-a8fd-10dccff833c6', NULL, 43, 43, 'He strictly ordered them that no one should know this, and commanded that something should be given to her to eat.'),
  ('1611cac9-5e24-5220-a53e-32e513b26bb1', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 1, 1, 'He went out from there. He came into his own country, and his disciples followed him.'),
  ('7a380bba-bfba-5d87-ae4a-ccaefb15c676', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 2, 2, 'When the Sabbath had come, he began to teach in the synagogue, and many hearing him were astonished, saying, "Where did this man get these things?" and, "What is the wisdom that is given to this man, that such mighty works come about by his hands?'),
  ('bc7ab778-8967-5bca-a34f-26eda0374d7a', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 3, 3, 'Isn''t this the carpenter, the son of Mary, and brother of James, Joses, Judah, and Simon? Aren''t his sisters here with us?" They were offended at him.'),
  ('311259e3-608a-51c0-a478-3d282818461a', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 4, 4, 'Jesus said to them, "A prophet is not without honor, except in his own country, and among his own relatives, and in his own house."'),
  ('de337754-cd8e-5fca-a901-45b302a7f8cb', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 5, 5, 'He could do no mighty work there, except that he laid his hands on a few sick people, and healed them.'),
  ('f4051f87-f2a8-5ea4-adab-5690d4ff0a7c', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 6, 6, 'He marveled because of their unbelief. He went around the villages teaching.'),
  ('12b294b3-7dea-5ead-ae97-038d77b7dec0', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 7, 7, 'He called to himself the twelve, and began to send them out two by two; and he gave them authority over the unclean spirits.'),
  ('0c2a17bc-7420-593c-a7c1-ba5a2734045e', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 8, 8, 'He commanded them that they should take nothing for their journey, except a staff only: no bread, no wallet, no money in their purse,'),
  ('1e518802-8d8d-5aa8-a7f3-12fc4a899635', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 9, 9, 'but to wear sandals, and not put on two tunics.'),
  ('da8ae5ec-41f7-5e2b-a2c7-9f52cd8a4fc0', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 10, 10, 'He said to them, "Wherever you enter into a house, stay there until you depart from there.'),
  ('4b843671-9701-5552-a1fb-3f218f86555c', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 11, 11, 'Whoever will not receive you nor hear you, as you depart from there, shake off the dust that is under your feet for a testimony against them. Assuredly, I tell you, it will be more tolerable for Sodom and Gomorrah in the day of judgment than for that city!"'),
  ('1254cd9c-002a-5698-afb7-6e1435838efc', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 12, 12, 'They went out and preached that people should repent.'),
  ('f571331e-d768-5fc5-a18b-8f80c6f49dec', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 13, 13, 'They cast out many demons, and anointed many with oil who were sick, and healed them.'),
  ('fd81ac32-8e98-5bae-ae69-16643d20100a', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 14, 14, 'King Herod heard this, for his name had become known, and he said, "John the Baptizer has risen from the dead, and therefore these powers are at work in him."'),
  ('6a30e146-022a-5ddf-ae93-f58091426cd4', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 15, 15, 'But others said, "He is Elijah." Others said, "He is a prophet, or like one of the prophets."'),
  ('34c27c1f-f199-5d6f-a178-82ecea2eea80', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 16, 16, 'But Herod, when he heard this, said, "This is John, whom I beheaded. He has risen from the dead."'),
  ('10efd5ca-d9ac-59ba-aa05-cc6dc901e9a2', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 17, 17, 'For Herod himself had sent out and arrested John, and bound him in prison for the sake of Herodias, his brother Philip''s wife, for he had married her.'),
  ('0258035c-38c9-5f2d-a73e-32a81b52bb8d', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 18, 18, 'For John said to Herod, "It is not lawful for you to have your brother''s wife."'),
  ('6541f30c-a023-583c-abce-64868fc4d8bb', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 19, 19, 'Herodias set herself against him, and desired to kill him, but she couldn''t,'),
  ('26818ec0-67fb-5ce3-a74f-c319e1cfb4e4', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 20, 20, 'for Herod feared John, knowing that he was a righteous and holy man, and kept him safe. When he heard him, he did many things, and he heard him gladly.'),
  ('6b1f2d41-d2f3-548e-a65e-4f6074436b89', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 21, 21, 'Then a convenient day came, that Herod on his birthday made a supper for his nobles, the high officers, and the chief men of Galilee.'),
  ('d2026743-616e-596e-a525-3ca07fb2615a', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 22, 22, 'When the daughter of Herodias herself came in and danced, she pleased Herod and those sitting with him. The king said to the young lady, "Ask me whatever you want, and I will give it to you."'),
  ('35f2a981-455f-58d9-a9cf-a2b0dd9f0db3', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 23, 23, 'He swore to her, "Whatever you shall ask of me, I will give you, up to half of my kingdom."'),
  ('75d0545f-e5f3-560f-a378-45a9bd3b7c36', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 24, 24, 'She went out, and said to her mother, "What shall I ask?" She said, "The head of John the Baptizer."'),
  ('21e12b58-ebe2-5013-ac18-b6e172929d32', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 25, 25, 'She came in immediately with haste to the king, and asked, "I want you to give me right now the head of John the Baptizer on a platter."'),
  ('e23d119c-21dd-5a92-a851-61a988cb4aaf', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 26, 26, 'The king was exceedingly sorry, but for the sake of his oaths, and of his dinner guests, he didn''t wish to refuse her.'),
  ('26f43f69-65cb-5b71-a390-3fae5b5d5ab1', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 27, 27, 'Immediately the king sent out a soldier of his guard, and commanded to bring John''s head, and he went and beheaded him in the prison,'),
  ('291fcf3c-4133-5a66-a6f8-64aa950f7a8c', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 28, 28, 'and brought his head on a platter, and gave it to the young lady; and the young lady gave it to her mother.'),
  ('b5b82bfe-9a14-5eef-a3e4-469d1bfcb990', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 29, 29, 'When his disciples heard this, they came and took up his corpse, and laid it in a tomb.'),
  ('81ffd23a-da09-502c-a869-6b77d9127bac', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 30, 30, 'The apostles gathered themselves together to Jesus, and they told him all things, whatever they had done, and whatever they had taught.'),
  ('4c34b15b-234f-5f21-ade3-2ce86860ce6c', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 31, 31, 'He said to them, "You come apart into a deserted place, and rest awhile." For there were many coming and going, and they had no leisure so much as to eat.'),
  ('3cc769aa-8660-59d7-a156-fea6784a161a', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 32, 32, 'They went away in the boat to a deserted place by themselves.'),
  ('6df15bb2-5612-56a3-a701-ba3eb0926c24', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 33, 33, 'They saw them going, and many recognized him and ran there on foot from all the cities. They arrived before them and came together to him.'),
  ('00dcecc7-186b-5fc1-a955-4795f68f47f9', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 34, 34, 'Jesus came out, saw a great multitude, and he had compassion on them, because they were like sheep without a shepherd, and he began to teach them many things.'),
  ('2c651eea-623a-58e5-a70a-f4279716490b', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 35, 35, 'When it was late in the day, his disciples came to him, and said, "This place is deserted, and it is late in the day.'),
  ('753325af-8c44-5b2e-a117-916edaa8457e', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 36, 36, 'Send them away, that they may go into the surrounding country and villages, and buy themselves bread, for they have nothing to eat."'),
  ('8a96f0bc-b2ed-5ad8-a16a-1948c3a658f7', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 37, 37, 'But he answered them, "You give them something to eat." They asked him, "Shall we go and buy two hundred denarii worth of bread, and give them something to eat?"'),
  ('bf790215-fde2-5067-ae34-f60b34108efe', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 38, 38, 'He said to them, "How many loaves do you have? Go see." When they knew, they said, "Five, and two fish."'),
  ('33072d05-9641-58ec-a042-a565b928af4c', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 39, 39, 'He commanded them that everyone should sit down in groups on the green grass.'),
  ('1f4d34e4-87bd-56a6-aecb-3cf9f94e5863', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 40, 40, 'They sat down in ranks, by hundreds and by fifties.'),
  ('225f0810-b887-5a54-ae97-96be42c2b8f2', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 41, 41, 'He took the five loaves and the two fish, and looking up to heaven, he blessed and broke the loaves, and he gave to his disciples to set before them, and he divided the two fish among them all.'),
  ('b2d0245a-a1e7-5575-a169-260ad7b8c0ca', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 42, 42, 'They all ate, and were filled.'),
  ('eb32dd9c-f362-5b6c-a7e8-a0f8c28c8428', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 43, 43, 'They took up twelve baskets full of broken pieces and also of the fish.'),
  ('1740bfb9-895c-5d99-a8b9-524c4fcdd1d7', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 44, 44, 'Those who ate the loaves were five thousand men.'),
  ('abbede07-217c-574d-a0fd-a376570bd95e', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 45, 45, 'Immediately he made his disciples get into the boat, and to go ahead to the other side, to Bethsaida, while he himself sent the multitude away.'),
  ('6fd72fda-6da8-5487-a412-8490e2e23357', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 46, 46, 'After he had taken leave of them, he went up the mountain to pray.'),
  ('66d81f82-111a-5c6b-ab00-f2f9b338eb33', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 47, 47, 'When evening had come, the boat was in the midst of the sea, and he was alone on the land.'),
  ('11bd715a-c0c1-5ab6-a50c-a56e6aaaff3f', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 48, 48, 'Seeing them distressed in rowing, for the wind was contrary to them, about the fourth watch of the night he came to them, walking on the sea, and he would have passed by them,'),
  ('4f4c5004-1863-575b-a5b7-ef0561308704', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 49, 49, 'but they, when they saw him walking on the sea, supposed that it was a ghost, and cried out;'),
  ('2df5006f-8f49-5420-a06c-602669d2bbd7', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 50, 50, 'for they all saw him, and were troubled. But he immediately spoke with them, and said to them, "Cheer up! It is I! Don''t be afraid."'),
  ('55ffb0b1-3de0-5eb1-ab00-39ebade0cf31', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 51, 51, 'He got into the boat with them; and the wind ceased, and they were very amazed among themselves, and marveled;'),
  ('f64faf21-a90f-5d6d-af5c-1fe93f6dcf4a', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 52, 52, 'for they hadn''t understood about the loaves, but their hearts were hardened.'),
  ('2f1fa46d-309f-5f94-ade6-37af255cc961', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 53, 53, 'When they had crossed over, they came to land at Gennesaret, and moored to the shore.'),
  ('be6f7201-d4f2-583e-aadb-d56a4fd03b83', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 54, 54, 'When they had come out of the boat, immediately the people recognized him,'),
  ('fec769ac-3dd4-5773-af14-d2de340f9a9a', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 55, 55, 'and ran around that whole region, and began to bring those who were sick, on their mats, to where they heard he was.'),
  ('13600599-2365-59d8-a91e-ea231177a142', '80597abe-8fbd-5be5-a99f-bef9d6b3dbab', NULL, 56, 56, 'Wherever he entered, into villages, or into cities, or into the country, they laid the sick in the marketplaces, and begged him that they might touch just the fringe of his garment; and as many as touched him were made well.'),
  ('7f1f62d8-3b40-5e61-aca6-ebb0c1def1b1', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 1, 1, 'Then the Pharisees, and some of the scribes gathered together to him, having come from Jerusalem.'),
  ('71f4d862-3753-52bd-a7b3-354de8712072', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 2, 2, 'Now when they saw some of his disciples eating bread with defiled, that is, unwashed, hands, they found fault.'),
  ('953e3655-c52c-5a35-a83a-e679bfbcb37d', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 3, 3, '(For the Pharisees, and all the Jews, don''t eat unless they wash their hands and forearms, holding to the tradition of the elders.'),
  ('036b6bcf-9713-560f-a5c6-07f4d9ffc0d7', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 4, 4, 'They don''t eat when they come from the marketplace, unless they bathe themselves, and there are many other things, which they have received to hold to: washings of cups, pitchers, bronze vessels, and couches.)'),
  ('a044b09e-6c1d-520e-a849-58a7865ae280', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 5, 5, 'The Pharisees and the scribes asked him, "Why don''t your disciples walk according to the tradition of the elders, but eat their bread with unwashed hands?"'),
  ('057dd5f4-ea1a-5096-ae03-759ce4d964b0', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 6, 6, 'He answered them, "Well did Isaiah prophesy of you hypocrites, as it is written, ''This people honors me with their lips, but their heart is far from me.'),
  ('52808cff-4031-58a7-a6a9-18981ceefa7d', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 7, 7, 'But in vain do they worship me, teaching as doctrines the commandments of men.'''),
  ('190f6e26-2a61-5e64-a215-04e538c68f31', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 8, 8, '"For you set aside the commandment of God, and hold tightly to the tradition of men--the washing of pitchers and cups, and you do many other such things."'),
  ('8e17c1b5-a7d9-5837-a8b9-935aea7c6751', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 9, 9, 'He said to them, "Full well do you reject the commandment of God, that you may keep your tradition.'),
  ('bf874b4f-a1e2-56d0-ae52-4f9cf6c65f15', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 10, 10, 'For Moses said, ''Honor your father and your mother;'' and, ''He who speaks evil of father or mother, let him be put to death.'''),
  ('6af49f19-24e5-5d04-a80e-e8be0e735d82', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 11, 11, 'But you say, ''If a man tells his father or his mother, "Whatever profit you might have received from me is Corban, that is to say, given to God;"'''),
  ('3a60b7a2-a2f4-5800-a40d-a102282aeb70', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 12, 12, 'then you no longer allow him to do anything for his father or his mother,'),
  ('7de217d0-c1ce-52c3-a262-c2255c43a5d5', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 13, 13, 'making void the word of God by your tradition, which you have handed down. You do many things like this."'),
  ('e2d69cde-3389-51b0-a435-6fca597f4543', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 14, 14, 'He called all the multitude to himself, and said to them, "Hear me, all of you, and understand.'),
  ('3ec202fb-d9bc-55dd-ad2b-90925563a9b1', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 15, 15, 'There is nothing from outside of the man, that going into him can defile him; but the things which proceed out of the man are those that defile the man.'),
  ('24824088-8615-5da4-a820-d742cd4be3f7', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 16, 16, 'If anyone has ears to hear, let him hear!"'),
  ('694f1426-8240-5cd1-a657-9771779c3d81', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 17, 17, 'When he had entered into a house away from the multitude, his disciples asked him about the parable.'),
  ('ea2f5222-4b97-5ce3-a304-6ed49b42c596', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 18, 18, 'He said to them, "Are you thus without understanding also? Don''t you perceive that whatever goes into the man from outside can''t defile him,'),
  ('fe252bda-d40a-521d-a595-5cf92b9461bf', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 19, 19, 'because it doesn''t go into his heart, but into his stomach, then into the latrine, thus purifying all foods?"'),
  ('cf02508b-79ed-5932-a766-3ea0b00d2693', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 20, 20, 'He said, "That which proceeds out of the man, that defiles the man.'),
  ('48a3ff8b-11bf-59bf-a576-9e33750fb741', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 21, 21, 'For from within, out of the hearts of men, proceed evil thoughts, adulteries, sexual sins, murders, thefts,'),
  ('0ef1144b-b8e6-5eb9-a13d-d414b4560c24', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 22, 22, 'covetings, wickedness, deceit, lustful desires, an evil eye, blasphemy, pride, and foolishness.'),
  ('83afd594-a253-5cdd-a48a-cea96bedb4c2', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 23, 23, 'All these evil things come from within, and defile the man."'),
  ('d0717788-b6db-50c3-a608-f284f29b4f2b', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 24, 24, 'From there he arose, and went away into the borders of Tyre and Sidon. He entered into a house, and didn''t want anyone to know it, but he couldn''t escape notice.'),
  ('2bf48a18-57cc-59a5-abf0-0b6a5d72281b', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 25, 25, 'For a woman, whose little daughter had an unclean spirit, having heard of him, came and fell down at his feet.'),
  ('86e35974-33c5-598e-a802-0e0b6b18d310', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 26, 26, 'Now the woman was a Greek, a Syrophoenician by race. She begged him that he would cast the demon out of her daughter.'),
  ('735319bc-7b30-5654-ae1b-e3b5971addc2', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 27, 27, 'But Jesus said to her, "Let the children be filled first, for it is not appropriate to take the children''s bread and throw it to the dogs."'),
  ('dd14d9f9-061b-5dec-abfe-0e3f77432c18', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 28, 28, 'But she answered him, "Yes, Lord. Yet even the dogs under the table eat the children''s crumbs."'),
  ('73384711-2e97-5d6a-a4c1-fb9579a03a18', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 29, 29, 'He said to her, "For this saying, go your way. The demon has gone out of your daughter."'),
  ('468c44a0-5fa7-517a-a4a9-1d777944c868', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 30, 30, 'She went away to her house, and found the child having been laid on the bed, with the demon gone out.'),
  ('636e1df1-cd60-58f8-a2c5-ebffb11be625', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 31, 31, 'Again he departed from the borders of Tyre and Sidon, and came to the sea of Galilee, through the midst of the region of Decapolis.'),
  ('42102c8e-e819-5d0d-a4f2-631d5a55fcb0', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 32, 32, 'They brought to him one who was deaf and had an impediment in his speech. They begged him to lay his hand on him.'),
  ('a47e63a5-9095-5cf6-a7af-7bf12e189aa4', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 33, 33, 'He took him aside from the multitude, privately, and put his fingers into his ears, and he spat, and touched his tongue.'),
  ('ab8dff98-b1fe-5025-ac6e-7f6de32cfa4f', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 34, 34, 'Looking up to heaven, he sighed, and said to him, "Ephphatha!" that is, "Be opened!"'),
  ('3b0bb868-2913-5304-a7cf-cf817d54c403', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 35, 35, 'Immediately his ears were opened, and the impediment of his tongue was released, and he spoke clearly.'),
  ('37410d87-847f-589f-a73c-54637226fcdf', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 36, 36, 'He commanded them that they should tell no one, but the more he commanded them, so much the more widely they proclaimed it.'),
  ('e607e377-ebb0-5c09-ab5b-d39767812658', '889306f0-73af-5b1f-a038-b04e59f29515', NULL, 37, 37, 'They were astonished beyond measure, saying, "He has done all things well. He makes even the deaf hear, and the mute speak!"'),
  ('560e0578-4e61-562d-afc3-d7d32a83ed9e', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 1, 1, 'In those days, when there was a very great multitude, and they had nothing to eat, Jesus called his disciples to himself, and said to them,'),
  ('386a3490-28cc-54f9-a2f1-394c1758a0ae', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 2, 2, '"I have compassion on the multitude, because they have stayed with me now three days, and have nothing to eat.'),
  ('ab21a302-1f75-52de-acb8-8bec1f1f5bfd', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 3, 3, 'If I send them away fasting to their home, they will faint on the way, for some of them have come a long way."'),
  ('7517056f-4622-55d2-a7ab-53f1cc1a334e', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 4, 4, 'His disciples answered him, "From where could one satisfy these people with bread here in a deserted place?"'),
  ('0490f503-51b6-59de-abc8-b8aabf8b56a8', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 5, 5, 'He asked them, "How many loaves do you have?" They said, "Seven."'),
  ('9272fa72-5a67-533b-aabd-fa3227ae7084', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 6, 6, 'He commanded the multitude to sit down on the ground, and he took the seven loaves. Having given thanks, he broke them, and gave them to his disciples to serve, and they served the multitude.'),
  ('bd498e03-f8f2-5d83-a30e-12a7138b4eb4', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 7, 7, 'They had a few small fish. Having blessed them, he said to serve these also.'),
  ('6ee11700-1ab2-5df2-a162-391c398766f7', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 8, 8, 'They ate, and were filled. They took up seven baskets of broken pieces that were left over.'),
  ('68779d36-906c-5cf7-ad28-58a626dba6c0', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 9, 9, 'Those who had eaten were about four thousand. Then he sent them away.'),
  ('39d32548-196d-5b4b-a90c-67d3026d5377', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 10, 10, 'Immediately he entered into the boat with his disciples, and came into the region of Dalmanutha.'),
  ('0b88ec35-23db-568a-a1ed-304cf899193e', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 11, 11, 'The Pharisees came out and began to question him, seeking from him a sign from heaven, and testing him.'),
  ('97faa9ef-4d0f-543d-ae2c-5f551538f53b', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 12, 12, 'He sighed deeply in his spirit, and said, "Why does this generation seek a sign? Most certainly I tell you, no sign will be given to this generation."'),
  ('c0700eb9-3ad1-5103-a426-aef066533c52', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 13, 13, 'He left them, and again entering into the boat, departed to the other side.'),
  ('05474597-6d3d-5b05-a6c7-ce44bdeadd87', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 14, 14, 'They forgot to take bread; and they didn''t have more than one loaf in the boat with them.'),
  ('4ac8fc34-6277-5c73-a448-3eb32c12bc88', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 15, 15, 'He warned them, saying, "Take heed: beware of the yeast of the Pharisees and the yeast of Herod."'),
  ('c95f03d9-68da-57df-a2a8-4398ebc8efc0', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 16, 16, 'They reasoned with one another, saying, "It''s because we have no bread."'),
  ('feb034ea-97ad-50a5-a52c-2893a52f8380', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 17, 17, 'Jesus, perceiving it, said to them, "Why do you reason that it''s because you have no bread? Don''t you perceive yet, neither understand? Is your heart still hardened?'),
  ('1d5bde68-3520-5680-ad9d-859834dbfb72', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 18, 18, 'Having eyes, don''t you see? Having ears, don''t you hear? Don''t you remember?'),
  ('028c46a1-efb0-5ba2-a0c0-dd7c017c2e10', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 19, 19, 'When I broke the five loaves among the five thousand, how many baskets full of broken pieces did you take up?" They told him, "Twelve."'),
  ('513ba5e4-ba48-5905-aa8e-2d138a5ecc7a', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 20, 20, '"When the seven loaves fed the four thousand, how many baskets full of broken pieces did you take up?" They told him, "Seven."'),
  ('0cc980fc-34a2-59d2-a599-afa0217df8fd', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 21, 21, 'He asked them, "Don''t you understand, yet?"'),
  ('f648ff15-5132-5750-a05e-38564828b092', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 22, 22, 'He came to Bethsaida. They brought a blind man to him, and begged him to touch him.'),
  ('0b553230-b757-555f-a285-91cdd09cd7dc', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 23, 23, 'He took hold of the blind man by the hand, and brought him out of the village. When he had spit on his eyes, and laid his hands on him, he asked him if he saw anything.'),
  ('c1b3f772-2f68-529b-a3ee-b4a7478dc6dc', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 24, 24, 'He looked up, and said, "I see men; for I see them like trees walking."'),
  ('94c7668b-5b9d-51a7-a89d-a63bee0a7c74', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 25, 25, 'Then again he laid his hands on his eyes. He looked intently, and was restored, and saw everyone clearly.'),
  ('190272e0-29ec-575b-a227-a6e671d4bdb3', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 26, 26, 'He sent him away to his house, saying, "Don''t enter into the village, nor tell anyone in the village."'),
  ('d5c4883f-1c79-5457-a2c2-b5e7f6764f8f', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 27, 27, 'Jesus went out, with his disciples, into the villages of Caesarea Philippi. On the way he asked his disciples, "Who do men say that I am?"'),
  ('c06a5dab-7ba2-5be6-a5e6-5f014030286a', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 28, 28, 'They told him, "John the Baptizer, and others say Elijah, but others: one of the prophets."'),
  ('7f0e3b9e-3921-538f-ae36-31492efb4463', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 29, 29, 'He said to them, "But who do you say that I am?" Peter answered, "You are the Christ."'),
  ('f2941e66-f356-5e7b-ad77-819c4eb3f3d5', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 30, 30, 'He commanded them that they should tell no one about him.'),
  ('6108db2b-d44c-5117-aa8a-e5cdb0344b7d', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 31, 31, 'He began to teach them that the Son of Man must suffer many things, and be rejected by the elders, the chief priests, and the scribes, and be killed, and after three days rise again.'),
  ('c9039c66-e672-50c3-a284-a0ea96e372f6', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 32, 32, 'He spoke to them openly. Peter took him, and began to rebuke him.'),
  ('3d63e84b-383b-51cd-a3bf-c60385c37958', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 33, 33, 'But he, turning around, and seeing his disciples, rebuked Peter, and said, "Get behind me, Satan! For you have in mind not the things of God, but the things of men."'),
  ('5fb0180e-aa42-5297-a1ca-d6289d13872f', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 34, 34, 'He called the multitude to himself with his disciples, and said to them, "Whoever wants to come after me, let him deny himself, and take up his cross, and follow me.'),
  ('b5c5fd56-b3c9-5e37-a4b6-ec68cf800fd3', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 35, 35, 'For whoever wants to save his life will lose it; and whoever will lose his life for my sake and the sake of the Good News will save it.'),
  ('c091ea6a-7723-51d0-a29d-b7a06e40aa5d', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 36, 36, 'For what does it profit a man, to gain the whole world, and forfeit his life?'),
  ('90f357e7-59e1-5b78-a2d7-8213b68dc231', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 37, 37, 'For what will a man give in exchange for his life?'),
  ('b596adf5-141a-5372-aa74-fa6392fcd9c7', '3104cb42-d153-5870-a6a3-609a53936521', NULL, 38, 38, 'For whoever will be ashamed of me and of my words in this adulterous and sinful generation, the Son of Man also will be ashamed of him, when he comes in the glory of his Father with the holy angels."'),
  ('8b3a7c1d-1bd6-51bb-a1a8-58b743b3c28b', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 1, 1, 'He said to them, "Most certainly I tell you, there are some standing here who will in no way taste death until they see the Kingdom of God come with power."'),
  ('26353978-9dcf-5643-ae86-f032bc1bbaa4', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 2, 2, 'After six days Jesus took with him Peter, James, and John, and brought them up onto a high mountain privately by themselves, and he was changed into another form in front of them.'),
  ('b922ae01-33ca-5da3-ae7f-89dcb2e7d860', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 3, 3, 'His clothing became glistening, exceedingly white, like snow, such as no launderer on earth can whiten them.'),
  ('4cc2ddfd-0418-5e55-abf9-61ba2c2173e0', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 4, 4, 'Elijah and Moses appeared to them, and they were talking with Jesus.'),
  ('99611921-9080-557d-a2bd-e968e9c63fc4', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 5, 5, 'Peter answered Jesus, "Rabbi, it is good for us to be here. Let''s make three tents: one for you, one for Moses, and one for Elijah."'),
  ('61f88efb-661a-5fee-a9c0-b4e4132e6800', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 6, 6, 'For he didn''t know what to say, for they were very afraid.'),
  ('e5d0c396-e3f1-5f26-ad61-9172a5e41845', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 7, 7, 'A cloud came, overshadowing them, and a voice came out of the cloud, "This is my beloved Son. Listen to him."'),
  ('0fb6aaf7-2d89-572e-a1a6-b3c18687de09', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 8, 8, 'Suddenly looking around, they saw no one with them any more, except Jesus only.'),
  ('08ac3567-d673-5874-a164-2d7365dc75bb', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 9, 9, 'As they were coming down from the mountain, he commanded them that they should tell no one what things they had seen, until after the Son of Man had risen from the dead.'),
  ('b5725942-3b54-572f-a0fb-4400144a6735', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 10, 10, 'They kept this saying to themselves, questioning what the "rising from the dead" meant.'),
  ('d6bdd6c8-aacb-5d51-afe3-033dae22f8d1', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 11, 11, 'They asked him, saying, "Why do the scribes say that Elijah must come first?"'),
  ('21cea084-e96b-5760-ae8d-76c0a0179b9d', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 12, 12, 'He said to them, "Elijah indeed comes first, and restores all things. How is it written about the Son of Man, that he should suffer many things and be despised?'),
  ('44f6de24-e298-529f-a991-0d9208c596c8', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 13, 13, 'But I tell you that Elijah has come, and they have also done to him whatever they wanted to, even as it is written about him."'),
  ('7685f27e-d3b6-512c-aff0-7e3e50f52be5', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 14, 14, 'Coming to the disciples, he saw a great multitude around them, and scribes questioning them.'),
  ('020776a4-d193-5d76-ad03-50dddcafb5da', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 15, 15, 'Immediately all the multitude, when they saw him, were greatly amazed, and running to him greeted him.'),
  ('3f99658a-0668-5350-aff2-3cdf44a1edf3', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 16, 16, 'He asked the scribes, "What are you asking them?"'),
  ('8636704a-4410-54e2-acc9-e9644dbb7926', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 17, 17, 'One of the multitude answered, "Teacher, I brought to you my son, who has a mute spirit;'),
  ('66e665ec-a33c-5c1e-a4e7-145712dc948d', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 18, 18, 'and wherever it seizes him, it throws him down, and he foams at the mouth, and grinds his teeth, and wastes away. I asked your disciples to cast it out, and they weren''t able."'),
  ('dfb095aa-0454-5810-ac0b-6203da0f847a', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 19, 19, 'He answered him, "Unbelieving generation, how long shall I be with you? How long shall I bear with you? Bring him to me."'),
  ('2343e991-98dc-5cb3-a2c0-11eb037d3c86', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 20, 20, 'They brought him to him, and when he saw him, immediately the spirit convulsed him, and he fell on the ground, wallowing and foaming at the mouth.'),
  ('679dcddf-d577-5573-ada3-0932625f3987', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 21, 21, 'He asked his father, "How long has it been since this has come to him?" He said, "From childhood.'),
  ('6e7f9fd2-ae6f-56ea-a6ae-54c07f13e7fc', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 22, 22, 'Often it has cast him both into the fire and into the water, to destroy him. But if you can do anything, have compassion on us, and help us."'),
  ('11b84581-511b-5040-a744-2e5e6e26efd2', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 23, 23, 'Jesus said to him, "If you can believe, all things are possible to him who believes."'),
  ('1228da73-f884-5e33-ab3e-4416054c511f', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 24, 24, 'Immediately the father of the child cried out with tears, "I believe. Help my unbelief!"'),
  ('b8f61fbf-8441-5ca9-ad83-36da29b7764b', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 25, 25, 'When Jesus saw that a multitude came running together, he rebuked the unclean spirit, saying to him, "You mute and deaf spirit, I command you, come out of him, and never enter him again!"'),
  ('29020028-da65-50c0-a32c-35f090ab0433', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 26, 26, 'Having cried out, and convulsed greatly, it came out of him. The boy became like one dead; so much that most of them said, "He is dead."'),
  ('5fd1558e-59db-5a03-a2d0-68bd9be4f64d', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 27, 27, 'But Jesus took him by the hand, and raised him up; and he arose.'),
  ('7a858ea5-9409-51a3-abc1-f81b905cfb0c', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 28, 28, 'When he had come into the house, his disciples asked him privately, "Why couldn''t we cast it out?"'),
  ('9695bb6f-471f-5ef7-a2ae-dcebb4257eae', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 29, 29, 'He said to them, "This kind can come out by nothing, except by prayer and fasting."'),
  ('c31265f4-2e0c-567b-ad5d-7974617da9bb', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 30, 30, 'They went out from there, and passed through Galilee. He didn''t want anyone to know it.'),
  ('51e3a396-3219-5d21-a71e-c391d358cbda', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 31, 31, 'For he was teaching his disciples, and said to them, "The Son of Man is being handed over to the hands of men, and they will kill him; and when he is killed, on the third day he will rise again."'),
  ('63cef493-6698-535c-a15a-add666cd8bfe', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 32, 32, 'But they didn''t understand the saying, and were afraid to ask him.'),
  ('33460b00-5bef-5a73-a8f3-2a9f4822e0b8', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 33, 33, 'He came to Capernaum, and when he was in the house he asked them, "What were you arguing among yourselves on the way?"'),
  ('59bc5b38-30f6-5cd4-ac67-5a3c28052043', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 34, 34, 'But they were silent, for they had disputed one with another on the way about who was the greatest.'),
  ('be0e977a-7f57-5d1f-a5ac-f58c6948fd24', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 35, 35, 'He sat down, and called the twelve; and he said to them, "If any man wants to be first, he shall be last of all, and servant of all."'),
  ('f5835f79-9686-501a-a437-59c29d5ac353', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 36, 36, 'He took a little child, and set him in the midst of them. Taking him in his arms, he said to them,'),
  ('5bc63246-526d-54ee-ac24-8141fd58e864', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 37, 37, '"Whoever receives one such little child in my name, receives me, and whoever receives me, doesn''t receive me, but him who sent me."'),
  ('e40c054c-ae7f-52af-a33b-f111f76ab5eb', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 38, 38, 'John said to him, "Teacher, we saw someone who doesn''t follow us casting out demons in your name; and we forbade him, because he doesn''t follow us."'),
  ('fc55ec52-ec01-5b87-a52f-55157e9dd034', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 39, 39, 'But Jesus said, "Don''t forbid him, for there is no one who will do a mighty work in my name, and be able quickly to speak evil of me.'),
  ('ddc20c17-5ac3-5640-aff3-c340e2e308ed', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 40, 40, 'For whoever is not against us is on our side.'),
  ('d0a6fe41-c9ac-59e4-a815-4a4b8b8130e3', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 41, 41, 'For whoever will give you a cup of water to drink in my name, because you are Christ''s, most certainly I tell you, he will in no way lose his reward.'),
  ('ac011799-2593-597c-abd3-6475a5c631cf', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 42, 42, 'Whoever will cause one of these little ones who believe in me to stumble, it would be better for him if he was thrown into the sea with a millstone hung around his neck.'),
  ('e4e513fa-f3e0-5886-a9d3-a25987e3317f', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 43, 43, 'If your hand causes you to stumble, cut it off. It is better for you to enter into life maimed, rather than having your two hands to go into Gehenna, into the unquenchable fire,'),
  ('12e2b820-5e51-5e15-a601-e1fce2b8f723', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 44, 44, '''where their worm doesn''t die, and the fire is not quenched.'''),
  ('b6abe346-1366-5da2-a3d5-5619ce6c2106', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 45, 45, 'If your foot causes you to stumble, cut it off. It is better for you to enter into life lame, rather than having your two feet to be cast into Gehenna, into the fire that will never be quenched--'),
  ('62cb8693-d91c-5ce4-a31a-6a52512d2db3', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 46, 46, '''where their worm doesn''t die, and the fire is not quenched.'''),
  ('69a3af80-23b9-5aab-a088-67365f348a2c', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 47, 47, 'If your eye causes you to stumble, cast it out. It is better for you to enter into the Kingdom of God with one eye, rather than having two eyes to be cast into the Gehenna of fire,'),
  ('038d6c03-f84a-5de5-ab75-6587cbb3612a', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 48, 48, '''where their worm doesn''t die, and the fire is not quenched.'''),
  ('46c51859-a44e-52e3-a935-0ad3fa9b88eb', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 49, 49, 'For everyone will be salted with fire, and every sacrifice will be seasoned with salt.'),
  ('832bd36a-1873-5db4-abee-3d792b8aa363', '335e7fd1-baba-5536-a513-8047870e6b91', NULL, 50, 50, 'Salt is good, but if the salt has lost its saltiness, with what will you season it? Have salt in yourselves, and be at peace with one another."'),
  ('f3f8ca8a-406f-5726-a66a-70fdb96f02ee', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 1, 1, 'He arose from there and came into the borders of Judea and beyond the Jordan. Multitudes came together to him again. As he usually did, he was again teaching them.'),
  ('ea4fcac4-52aa-5ba7-a945-11ebdf8b6dc9', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 2, 2, 'Pharisees came to him testing him, and asked him, "Is it lawful for a man to divorce his wife?"'),
  ('132b32bf-e3cf-54bd-a678-7c866be44cd6', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 3, 3, 'He answered, "What did Moses command you?"'),
  ('7616fea8-fec8-5a69-a791-3984fcc17282', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 4, 4, 'They said, "Moses allowed a certificate of divorce to be written, and to divorce her."'),
  ('e0a1ed3e-7580-5339-add2-4c5230f4e8e6', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 5, 5, 'But Jesus said to them, "For your hardness of heart, he wrote you this commandment.'),
  ('b85e0db8-c73b-53ba-a897-1fbb6ab9ce80', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 6, 6, 'But from the beginning of the creation, God made them male and female.'),
  ('948c1f19-7bd3-5fad-aaee-088106dd16a9', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 7, 7, 'For this cause a man will leave his father and mother, and will join to his wife,'),
  ('f5eb26db-3646-5142-a56c-340914a5ca2e', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 8, 8, 'and the two will become one flesh, so that they are no longer two, but one flesh.'),
  ('a1dfe729-1f07-561f-a969-e1e3573db3df', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 9, 9, 'What therefore God has joined together, let no man separate."'),
  ('fea62a81-b032-5117-abf9-b5c4fb934224', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 10, 10, 'In the house, his disciples asked him again about the same matter.'),
  ('88777d71-acec-5642-a3ef-67bd7277cd08', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 11, 11, 'He said to them, "Whoever divorces his wife, and marries another, commits adultery against her.'),
  ('a722374d-4087-5ed4-a72a-e6222dd44c26', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 12, 12, 'If a woman herself divorces her husband, and marries another, she commits adultery."'),
  ('4c361ebc-749c-573f-a677-f10398da343f', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 13, 13, 'They were bringing to him little children, that he should touch them, but the disciples rebuked those who were bringing them.'),
  ('e01ffe60-3eab-5ac0-a66d-f4407270082e', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 14, 14, 'But when Jesus saw it, he was moved with indignation, and said to them, "Allow the little children to come to me! Don''t forbid them, for the Kingdom of God belongs to such as these.'),
  ('7de91c5c-810a-5023-a0cf-5fa16d0bcabd', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 15, 15, 'Most certainly I tell you, whoever will not receive the Kingdom of God like a little child, he will in no way enter into it."'),
  ('85716a76-ea06-5f1b-a0ff-8214db8c8a36', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 16, 16, 'He took them in his arms, and blessed them, laying his hands on them.'),
  ('31e53912-c9b1-552b-a01e-a6e1c33ca48b', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 17, 17, 'As he was going out into the way, one ran to him, knelt before him, and asked him, "Good Teacher, what shall I do that I may inherit eternal life?"'),
  ('1cf85f4a-60f1-5757-a2d9-f7d2eb9612a9', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 18, 18, 'Jesus said to him, "Why do you call me good? No one is good except one--God.'),
  ('65322a6d-b9c0-5201-a791-caeb3fa36787', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 19, 19, 'You know the commandments: ''Do not murder,'' ''Do not commit adultery,'' ''Do not steal,'' ''Do not give false testimony,'' ''Do not defraud,'' ''Honor your father and mother.''"'),
  ('b4a83e60-da71-5887-aa38-855466fe486b', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 20, 20, 'He said to him, "Teacher, I have observed all these things from my youth."'),
  ('89b91f22-2fad-5784-ae6f-0366a592ec28', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 21, 21, 'Jesus looking at him loved him, and said to him, "One thing you lack. Go, sell whatever you have, and give to the poor, and you will have treasure in heaven; and come, follow me, taking up the cross."'),
  ('c60ab693-4ec8-501e-a6ec-b4b2f7ff1cec', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 22, 22, 'But his face fell at that saying, and he went away sorrowful, for he was one who had great possessions.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('e5057df4-d01c-5ba0-a71c-cd78d3537f20', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 23, 23, 'Jesus looked around, and said to his disciples, "How difficult it is for those who have riches to enter into the Kingdom of God!"'),
  ('433b3c0f-a428-5108-a292-77685f42bfba', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 24, 24, 'The disciples were amazed at his words. But Jesus answered again, "Children, how hard is it for those who trust in riches to enter into the Kingdom of God!'),
  ('539a75fa-2b8c-53f1-a7a8-e5fce622397b', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 25, 25, 'It is easier for a camel to go through a needle''s eye than for a rich man to enter into the Kingdom of God."'),
  ('3cbf06f0-9bf1-5019-a83c-a2c88c2c5ffb', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 26, 26, 'They were exceedingly astonished, saying to him, "Then who can be saved?"'),
  ('aa59ed90-273c-5e08-a790-c5290b16d80f', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 27, 27, 'Jesus, looking at them, said, "With men it is impossible, but not with God, for all things are possible with God."'),
  ('1c092638-296b-58ff-a290-c284d77f17a2', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 28, 28, 'Peter began to tell him, "Behold, we have left all, and have followed you."'),
  ('3789b8a6-5907-5d7d-adda-041976416a20', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 29, 29, 'Jesus said, "Most certainly I tell you, there is no one who has left house, or brothers, or sisters, or father, or mother, or wife, or children, or land, for my sake, and for the sake of the Good News,'),
  ('b16ebeb2-916f-52a8-afa2-a9106718a325', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 30, 30, 'but he will receive one hundred times more now in this time, houses, brothers, sisters, mothers, children, and land, with persecutions; and in the age to come eternal life.'),
  ('1efd7bbe-c2d1-5dbe-a814-96ebe1211876', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 31, 31, 'But many who are first will be last; and the last first."'),
  ('ab096a32-d84d-5e1a-a5ed-b9c4d1300081', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 32, 32, 'They were on the way, going up to Jerusalem; and Jesus was going in front of them, and they were amazed; and those who followed were afraid. He again took the twelve, and began to tell them the things that were going to happen to him.'),
  ('541f0be7-8b72-5941-aa2a-6f6b4ec88589', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 33, 33, '"Behold, we are going up to Jerusalem. The Son of Man will be delivered to the chief priests and the scribes. They will condemn him to death, and will deliver him to the Gentiles.'),
  ('2b00df26-67a6-5eba-a26e-26a6af5fa33a', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 34, 34, 'They will mock him, spit on him, scourge him, and kill him. On the third day he will rise again."'),
  ('488c188e-205e-552d-a8fe-6f740c4bd87d', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 35, 35, 'James and John, the sons of Zebedee, came near to him, saying, "Teacher, we want you to do for us whatever we will ask."'),
  ('eb38ffac-cf73-52fa-ac6a-6a10ec7e734f', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 36, 36, 'He said to them, "What do you want me to do for you?"'),
  ('d8e3f258-e1a4-52a8-a75c-9111dbbd6691', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 37, 37, 'They said to him, "Grant to us that we may sit, one at your right hand, and one at your left hand, in your glory."'),
  ('379ecf0e-db1e-5b68-a5d1-cf3121d2f555', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 38, 38, 'But Jesus said to them, "You don''t know what you are asking. Are you able to drink the cup that I drink, and to be baptized with the baptism that I am baptized with?"'),
  ('ac4a7c57-b811-592e-a471-642217847980', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 39, 39, 'They said to him, "We are able." Jesus said to them, "You shall indeed drink the cup that I drink, and you shall be baptized with the baptism that I am baptized with;'),
  ('baae0ad5-5ece-58b8-a06e-649b3627a106', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 40, 40, 'but to sit at my right hand and at my left hand is not mine to give, but for whom it has been prepared."'),
  ('4761abf3-1e6f-59fe-aaae-34730761b86b', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 41, 41, 'When the ten heard it, they began to be indignant towards James and John.'),
  ('92a34d84-2c12-5ad3-a66b-27df4aae11f6', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 42, 42, 'Jesus summoned them, and said to them, "You know that they who are recognized as rulers over the nations lord it over them, and their great ones exercise authority over them.'),
  ('ef34d86b-bfab-5c03-adcd-3fc647e4561a', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 43, 43, 'But it shall not be so among you, but whoever wants to become great among you shall be your servant.'),
  ('8bbcea47-4de8-5ac3-ae4c-3692e8d95e4f', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 44, 44, 'Whoever of you wants to become first among you, shall be bondservant of all.'),
  ('65f7961b-26db-524c-a3a8-aa02e8c90927', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 45, 45, 'For the Son of Man also came not to be served, but to serve, and to give his life as a ransom for many."'),
  ('6c70cb33-fcde-596e-a05c-b7f24ea448ef', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 46, 46, 'They came to Jericho. As he went out from Jericho, with his disciples and a great multitude, the son of Timaeus, Bartimaeus, a blind beggar, was sitting by the road.'),
  ('afcac20d-99e3-5e02-a05c-4defe4a372d5', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 47, 47, 'When he heard that it was Jesus the Nazarene, he began to cry out, and say, "Jesus, you son of David, have mercy on me!"'),
  ('15168642-dde4-5e72-ad82-07bb9716d46c', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 48, 48, 'Many rebuked him, that he should be quiet, but he cried out much more, "You son of David, have mercy on me!"'),
  ('06bc430e-2c6f-518c-ab73-795ac87b70e3', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 49, 49, 'Jesus stood still, and said, "Call him." They called the blind man, saying to him, "Cheer up! Get up. He is calling you!"'),
  ('454e5ae3-1542-522c-a071-7b57287e1e02', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 50, 50, 'He, casting away his cloak, sprang up, and came to Jesus.'),
  ('64b44285-8c6d-56e3-a1f9-795e67decd06', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 51, 51, 'Jesus asked him, "What do you want me to do for you?" The blind man said to him, "Rabboni, that I may see again."'),
  ('f659217e-966e-5841-ab35-9e656dc73fa5', 'c3a68e02-f929-55ec-a2a1-f250368bf668', NULL, 52, 52, 'Jesus said to him, "Go your way. Your faith has made you well." Immediately he received his sight, and followed Jesus in the way.'),
  ('ff55aa8b-60cf-5428-adbc-72eff415f0e0', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 1, 1, 'When they drew near to Jerusalem, to Bethsphage and Bethany, at the Mount of Olives, he sent two of his disciples,'),
  ('b44aa470-1202-574c-a0fe-d830ae9449f6', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 2, 2, 'and said to them, "Go your way into the village that is opposite you. Immediately as you enter into it, you will find a young donkey tied, on which no one has sat. Untie him, and bring him.'),
  ('2237f0a3-4407-5b31-a41c-f32fe7ad3fc6', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 3, 3, 'If anyone asks you, ''Why are you doing this?'' say, ''The Lord needs him;'' and immediately he will send him back here."'),
  ('b726a099-4d38-520d-adec-b465178a34f8', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 4, 4, 'They went away, and found a young donkey tied at the door outside in the open street, and they untied him.'),
  ('64385530-f806-5e50-ac61-d1a5cb5cfb1b', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 5, 5, 'Some of those who stood there asked them, "What are you doing, untying the young donkey?"'),
  ('54e1d0d2-3c83-5595-a9fb-f78c8dd260c0', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 6, 6, 'They said to them just as Jesus had said, and they let them go.'),
  ('aa17791a-95b6-561c-ad93-8aa9eefa77b7', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 7, 7, 'They brought the young donkey to Jesus, and threw their garments on it, and Jesus sat on it.'),
  ('766d43c4-7f9a-5a20-a3ca-f21a613dac09', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 8, 8, 'Many spread their garments on the way, and others were cutting down branches from the trees, and spreading them on the road.'),
  ('922a50a5-9a6c-5816-a4ba-f8c6b796264f', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 9, 9, 'Those who went in front, and those who followed, cried out, "Hosanna! Blessed is he who comes in the name of the Lord!'),
  ('fc992348-e99c-5694-af09-350a55d7e757', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 10, 10, 'Blessed is the kingdom of our father David that is coming in the name of the Lord! Hosanna in the highest!"'),
  ('56f8cb0f-0776-586f-aaa5-93879f67a66a', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 11, 11, 'Jesus entered into the temple in Jerusalem. When he had looked around at everything, it being now evening, he went out to Bethany with the twelve.'),
  ('fd8a8309-0a59-53eb-a981-3140dc0efa1a', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 12, 12, 'The next day, when they had come out from Bethany, he was hungry.'),
  ('85d690af-4af4-5e74-abb4-9cbd4de53db7', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 13, 13, 'Seeing a fig tree afar off having leaves, he came to see if perhaps he might find anything on it. When he came to it, he found nothing but leaves, for it was not the season for figs.'),
  ('a061624d-1f68-5d3a-a258-aa797346cd92', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 14, 14, 'Jesus told it, "May no one ever eat fruit from you again!" and his disciples heard it.'),
  ('384d2619-964d-5084-affe-37d3a9c39bc5', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 15, 15, 'They came to Jerusalem, and Jesus entered into the temple, and began to throw out those who sold and those who bought in the temple, and overthrew the tables of the money changers, and the seats of those who sold the doves.'),
  ('2629c7be-eaed-5af5-ad75-6dba532b8b96', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 16, 16, 'He would not allow anyone to carry a container through the temple.'),
  ('3d3b0887-60ef-5d5b-a275-b0aac36696c8', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 17, 17, 'He taught, saying to them, "Isn''t it written, ''My house will be called a house of prayer for all the nations?'' But you have made it a den of robbers!"'),
  ('3bfcb889-6643-5520-af13-46356a859d05', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 18, 18, 'The chief priests and the scribes heard it, and sought how they might destroy him. For they feared him, because all the multitude was astonished at his teaching.'),
  ('35e19ea4-c54f-5100-abdf-4baf1f2b3503', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 19, 19, 'When evening came, he went out of the city.'),
  ('350aa0a3-7a57-5e45-a020-fc49cf1d23da', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 20, 20, 'As they passed by in the morning, they saw the fig tree withered away from the roots.'),
  ('7ec46fd6-907f-594b-a63a-bcd9ef3f95d1', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 21, 21, 'Peter, remembering, said to him, "Rabbi, look! The fig tree which you cursed has withered away."'),
  ('ef02360d-b5c9-5065-a2d7-6a437c51a429', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 22, 22, 'Jesus answered them, "Have faith in God.'),
  ('b8cf69e9-2857-5e06-ae7f-4566c7c9e13e', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 23, 23, 'For most certainly I tell you, whoever may tell this mountain, ''Be taken up and cast into the sea,'' and doesn''t doubt in his heart, but believes that what he says is happening; he shall have whatever he says.'),
  ('0feb1841-8a70-56c4-a4c5-a83d5a83b9d0', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 24, 24, 'Therefore I tell you, all things whatever you pray and ask for, believe that you have received them, and you shall have them.'),
  ('f45168ee-51b8-51f7-a510-be68c406ca55', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 25, 25, 'Whenever you stand praying, forgive, if you have anything against anyone; so that your Father, who is in heaven, may also forgive you your transgressions.'),
  ('dfc2e2cf-4ac7-56ff-a449-1a5a05e0c39e', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 26, 26, 'But if you do not forgive, neither will your Father in heaven forgive your transgressions."'),
  ('e1099801-9bc9-5c26-a6b6-3b7485faf40c', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 27, 27, 'They came again to Jerusalem, and as he was walking in the temple, the chief priests, and the scribes, and the elders came to him,'),
  ('61946c20-0c52-5ab2-a5ff-dc49a17ed79f', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 28, 28, 'and they began saying to him, "By what authority do you do these things? Or who gave you this authority to do these things?"'),
  ('ad772df5-cdaa-5778-ab44-d3eee37cc513', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 29, 29, 'Jesus said to them, "I will ask you one question. Answer me, and I will tell you by what authority I do these things.'),
  ('ce31ca5f-0963-524d-a26c-c03de899ce9e', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 30, 30, 'The baptism of John--was it from heaven, or from men? Answer me."'),
  ('c75f5e2c-c79f-593f-a201-9e1946e0ebe4', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 31, 31, 'They reasoned with themselves, saying, "If we should say, ''From heaven;'' he will say, ''Why then did you not believe him?'''),
  ('4e9c5c9e-9594-553d-a66e-137e72f1619f', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 32, 32, 'If we should say, ''From men''"--they feared the people, for all held John to really be a prophet.'),
  ('b663ef7c-b63f-5b25-ad9a-430102d8a9e5', '1e5e9c72-1ad7-5852-ac40-bc1d4bc8b26c', NULL, 33, 33, 'They answered Jesus, "We don''t know." Jesus said to them, "Neither do I tell you by what authority I do these things."'),
  ('536bc28b-3b55-5c84-a9ac-ca7cf7df2cff', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 1, 1, 'He began to speak to them in parables. "A man planted a vineyard, put a hedge around it, dug a pit for the winepress, built a tower, rented it out to a farmer, and went into another country.'),
  ('7486b761-2e1b-5b6e-af8a-932cc2367574', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 2, 2, 'When it was time, he sent a servant to the farmer to get from the farmer his share of the fruit of the vineyard.'),
  ('bddcc212-9713-5711-a4f5-df571fe2dd44', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 3, 3, 'They took him, beat him, and sent him away empty.'),
  ('7caf8c5b-43dc-5bdc-a0ad-6fff0501a977', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 4, 4, 'Again, he sent another servant to them; and they threw stones at him, wounded him in the head, and sent him away shamefully treated.'),
  ('0df9ebe9-bee2-5186-a5e3-d63907e2b83a', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 5, 5, 'Again he sent another; and they killed him; and many others, beating some, and killing some.'),
  ('9d92714e-7f21-5a6a-a9e6-b5a3c0f2f636', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 6, 6, 'Therefore still having one, his beloved son, he sent him last to them, saying, ''They will respect my son.'''),
  ('de4696fe-3f51-5ef7-a923-2981f372949f', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 7, 7, 'But those farmers said among themselves, ''This is the heir. Come, let''s kill him, and the inheritance will be ours.'''),
  ('36de0849-a165-5126-afee-c95a0979b684', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 8, 8, 'They took him, killed him, and cast him out of the vineyard.'),
  ('fb0ea8ea-6deb-5343-a709-7ec2ff218299', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 9, 9, 'What therefore will the lord of the vineyard do? He will come and destroy the farmers, and will give the vineyard to others.'),
  ('62f50132-0868-5d4d-afef-aa5d5450fe0b', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 10, 10, 'Haven''t you even read this Scripture: ''The stone which the builders rejected, the same was made the head of the corner.'),
  ('3d8cb61f-bc4e-5762-af57-696deaea785f', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 11, 11, 'This was from the Lord, it is marvelous in our eyes''?"'),
  ('248340a2-a24e-5c2b-aaf1-6f0cdb5b13ac', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 12, 12, 'They tried to seize him, but they feared the multitude; for they perceived that he spoke the parable against them. They left him, and went away.'),
  ('ad6a498c-9e5d-5ae8-af9b-78ab02be20b4', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 13, 13, 'They sent some of the Pharisees and of the Herodians to him, that they might trap him with words.'),
  ('2741017e-6b4a-53af-a0ba-6fb9f4173b9d', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 14, 14, 'When they had come, they asked him, "Teacher, we know that you are honest, and don''t defer to anyone; for you aren''t partial to anyone, but truly teach the way of God. Is it lawful to pay taxes to Caesar, or not?'),
  ('f92104b1-0009-56a0-a7ac-4c4e81760706', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 15, 15, 'Shall we give, or shall we not give?" But he, knowing their hypocrisy, said to them, "Why do you test me? Bring me a denarius, that I may see it."'),
  ('d93ccec0-45fd-5aff-a129-b179bb958bc4', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 16, 16, 'They brought it. He said to them, "Whose is this image and inscription?" They said to him, "Caesar''s."'),
  ('fa1499e3-77c3-5179-a683-473089ce9f6d', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 17, 17, 'Jesus answered them, "Render to Caesar the things that are Caesar''s, and to God the things that are God''s." They marveled greatly at him.'),
  ('bf90ac93-94db-5091-a710-6ff64a9c5025', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 18, 18, 'There came to him Sadducees, who say that there is no resurrection. They asked him, saying,'),
  ('6c04148f-8b28-5430-a0e7-56154fb92ad4', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 19, 19, '"Teacher, Moses wrote to us, ''If a man''s brother dies, and leaves a wife behind him, and leaves no children, that his brother should take his wife, and raise up offspring for his brother.'''),
  ('13f72db3-f993-5427-a07f-b798e412192c', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 20, 20, 'There were seven brothers. The first took a wife, and dying left no offspring.'),
  ('05b15337-b063-5059-aa0c-c5254a0eddfa', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 21, 21, 'The second took her, and died, leaving no children behind him. The third likewise;'),
  ('dc781ff8-33f3-5080-a8ce-58c3e3d7758b', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 22, 22, 'and the seven took her and left no children. Last of all the woman also died.'),
  ('c396ce04-4c9d-50dd-ac85-7d565b6a57cc', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 23, 23, 'In the resurrection, when they rise, whose wife will she be of them? For the seven had her as a wife."'),
  ('e5580aaf-8feb-5960-a1fc-bcc3f1c37609', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 24, 24, 'Jesus answered them, "Isn''t this because you are mistaken, not knowing the Scriptures, nor the power of God?'),
  ('96aca9ca-a262-5e20-a621-d244ab60e3ac', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 25, 25, 'For when they will rise from the dead, they neither marry, nor are given in marriage, but are like angels in heaven.'),
  ('9cd124f1-a920-59ac-a973-8dd4298fac25', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 26, 26, 'But about the dead, that they are raised; haven''t you read in the book of Moses, about the Bush, how God spoke to him, saying, ''I am the God of Abraham, the God of Isaac, and the God of Jacob''?'),
  ('797f5456-9752-59ec-a417-85d3c809edd0', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 27, 27, 'He is not the God of the dead, but of the living. You are therefore badly mistaken."'),
  ('54a9f8a9-077f-5a4b-a8b3-7e2acb84bbc7', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 28, 28, 'One of the scribes came, and heard them questioning together. Knowing that he had answered them well, asked him, "Which commandment is the greatest of all?"'),
  ('625f2fde-1055-545c-a136-495aae732e8e', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 29, 29, 'Jesus answered, "The greatest is, ''Hear, Israel, the Lord our God, the Lord is one:'),
  ('50439804-d4a8-5bd0-aae3-e089886143e7', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 30, 30, 'you shall love the Lord your God with all your heart, and with all your soul, and with all your mind, and with all your strength.'' This is the first commandment.'),
  ('92363dce-b0b3-5147-ad1f-174c0695ab83', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 31, 31, 'The second is like this, ''You shall love your neighbor as yourself.'' There is no other commandment greater than these."'),
  ('830e1052-38d1-5a3f-a41f-f519f94e0fb6', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 32, 32, 'The scribe said to him, "Truly, teacher, you have said well that he is one, and there is none other but he,'),
  ('c4a3bb5d-4ccc-5f94-accc-be472901c545', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 33, 33, 'and to love him with all the heart, and with all the understanding, with all the soul, and with all the strength, and to love his neighbor as himself, is more important than all whole burnt offerings and sacrifices."'),
  ('020283a0-b363-5998-a0d1-c02a71cdce17', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 34, 34, 'When Jesus saw that he answered wisely, he said to him, "You are not far from the Kingdom of God." No one dared ask him any question after that.'),
  ('de3abd04-70e8-51df-a610-30b32786162d', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 35, 35, 'Jesus responded, as he taught in the temple, "How is it that the scribes say that the Christ is the son of David?'),
  ('eeef3982-5c5c-5ebe-a8c2-36a969b89480', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 36, 36, 'For David himself said in the Holy Spirit, ''The Lord said to my Lord, "Sit at my right hand, until I make your enemies the footstool of your feet."'''),
  ('78b8dc15-9fc8-5002-a8e1-62911a0fbcbd', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 37, 37, 'Therefore David himself calls him Lord, so how can he be his son?" The common people heard him gladly.'),
  ('60eb3b9a-c5c5-54b9-a607-bd714ca85e94', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 38, 38, 'In his teaching he said to them, "Beware of the scribes, who like to walk in long robes, and to get greetings in the marketplaces,'),
  ('0ef10bac-2501-5ac5-a2b6-bba8dd5c0950', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 39, 39, 'and the best seats in the synagogues, and the best places at feasts:'),
  ('cf250157-2b3c-5da2-afe8-bc3442b90658', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 40, 40, 'those who devour widows'' houses, and for a pretense make long prayers. These will receive greater condemnation."'),
  ('05b3ddc4-a3e5-5679-ad36-0795cc15660b', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 41, 41, 'Jesus sat down opposite the treasury, and saw how the multitude cast money into the treasury. Many who were rich cast in much.'),
  ('34dd0eab-4a3a-54b5-a559-d72f842fde07', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 42, 42, 'A poor widow came, and she cast in two small brass coins, which equal a quadrans coin.'),
  ('c630318a-7f26-5f5a-a63d-5eb61c707d30', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 43, 43, 'He called his disciples to himself, and said to them, "Most certainly I tell you, this poor widow gave more than all those who are giving into the treasury,'),
  ('83394138-08fc-5a1f-a95f-aa2f9310837e', 'e3d5d9f8-122b-5a6b-aff8-5934b78a760d', NULL, 44, 44, 'for they all gave out of their abundance, but she, out of her poverty, gave all that she had to live on."'),
  ('e76b89a4-35d9-54a2-a7a6-6060ffce94dd', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 1, 1, 'As he went out of the temple, one of his disciples said to him, "Teacher, see what kind of stones and what kind of buildings!"'),
  ('65b263b3-f306-5a2a-a407-1b7986ce6d51', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 2, 2, 'Jesus said to him, "Do you see these great buildings? There will not be left here one stone on another, which will not be thrown down."'),
  ('0a0c3d80-c0c3-58a0-a2a5-f35beebcb12b', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 3, 3, 'As he sat on the Mount of Olives opposite the temple, Peter, James, John, and Andrew asked him privately,'),
  ('6ee04b53-c2b2-5747-a4e1-cc524c800fc5', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 4, 4, '"Tell us, when will these things be? What is the sign that these things are all about to be fulfilled?"'),
  ('a9ab1318-d946-5dc7-a470-f3e4d13c54b8', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 5, 5, 'Jesus, answering, began to tell them, "Be careful that no one leads you astray.'),
  ('5f1ffab8-d521-50d8-a235-307de0003c25', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 6, 6, 'For many will come in my name, saying, ''I am he!'' and will lead many astray.'),
  ('d9ee7632-a8c0-5948-af6c-16c8a6f9cdf6', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 7, 7, '"When you hear of wars and rumors of wars, don''t be troubled. For those must happen, but the end is not yet.'),
  ('fca1c23e-5905-59da-a82e-d51f43907cae', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 8, 8, 'For nation will rise against nation, and kingdom against kingdom. There will be earthquakes in various places. There will be famines and troubles. These things are the beginning of birth pains.'),
  ('8895ed6a-8034-5a51-ad5b-f3fddc35eb69', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 9, 9, 'But watch yourselves, for they will deliver you up to councils. You will be beaten in synagogues. You will stand before rulers and kings for my sake, for a testimony to them.'),
  ('95dfbbb0-b4a0-5f80-a5fe-26ebb905b2ed', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 10, 10, 'The Good News must first be preached to all the nations.'),
  ('5fed3d95-12c0-5269-a0f2-8e02bb86a9fd', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 11, 11, 'When they lead you away and deliver you up, don''t be anxious beforehand, or premeditate what you will say, but say whatever will be given you in that hour. For it is not you who speak, but the Holy Spirit.'),
  ('a816938e-665d-55e2-ae46-fa9c2fa0daa5', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 12, 12, '"Brother will deliver up brother to death, and the father his child. Children will rise up against parents, and cause them to be put to death.'),
  ('5fdd98c2-d37d-59ec-adaa-f6545cc9dcc4', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 13, 13, 'You will be hated by all men for my name''s sake, but he who endures to the end, the same will be saved.'),
  ('ad3db746-3300-5035-afcf-20d457482515', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 14, 14, 'But when you see the abomination of desolation, spoken of by Daniel the prophet, standing where it ought not (let the reader understand), then let those who are in Judea flee to the mountains,'),
  ('c5eed24b-80b6-5dd9-a63f-7be0cb8b25eb', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 15, 15, 'and let him who is on the housetop not go down, nor enter in, to take anything out of his house.'),
  ('fca6c42a-8c1b-5c9f-aaf5-61ca9c0eeea2', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 16, 16, 'Let him who is in the field not return back to take his cloak.'),
  ('83e0e138-ec3f-59e1-ab65-4b5920e402f3', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 17, 17, 'But woe to those who are with child and to those who nurse babies in those days!'),
  ('41c4f94b-3fdf-5c8e-a22b-1d50c1db9d2d', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 18, 18, 'Pray that your flight won''t be in the winter.'),
  ('fff58018-6a4e-50b9-affa-d90525ec5482', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 19, 19, 'For in those days there will be oppression, such as there has not been the like from the beginning of the creation which God created until now, and never will be.'),
  ('8ac18725-65ec-51d1-a5d4-0d393ebd0ba7', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 20, 20, 'Unless the Lord had shortened the days, no flesh would have been saved; but for the sake of the chosen ones, whom he picked out, he shortened the days.'),
  ('432ce8b8-3acf-5174-a3eb-7ad450855b97', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 21, 21, 'Then if anyone tells you, ''Look, here is the Christ!'' or, ''Look, there!'' don''t believe it.'),
  ('c9fbebb4-a5eb-5311-a553-42458f84cb59', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 22, 22, 'For there will arise false christs and false prophets, and will show signs and wonders, that they may lead astray, if possible, even the chosen ones.'),
  ('5e67ef92-ec7d-58b8-a316-1b49cac78dc3', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 23, 23, 'But you watch. "Behold, I have told you all things beforehand.'),
  ('d0607999-c910-5a27-a15b-58cce9377bc7', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 24, 24, 'But in those days, after that oppression, the sun will be darkened, the moon will not give its light,'),
  ('102ed179-81a3-5676-a575-abc304bf0d0b', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 25, 25, 'the stars will be falling from the sky, and the powers that are in the heavens will be shaken.'),
  ('23fe40c8-8ebc-59fa-ae0e-5802ef28b72b', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 26, 26, 'Then they will see the Son of Man coming in clouds with great power and glory.'),
  ('38a5eb91-a00d-5b3a-aaee-1a32619776ca', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 27, 27, 'Then he will send out his angels, and will gather together his chosen ones from the four winds, from the ends of the earth to the ends of the sky.'),
  ('133b3ca9-f139-5eac-a41b-a022d9000b06', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 28, 28, '"Now from the fig tree, learn this parable. When the branch has now become tender, and puts forth its leaves, you know that the summer is near;'),
  ('0cf7e1c4-4df8-51a9-a1e2-02414507a8a2', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 29, 29, 'even so you also, when you see these things coming to pass, know that it is near, at the doors.'),
  ('040f9256-0720-5e32-a2c7-de517631a202', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 30, 30, 'Most certainly I say to you, this generation will not pass away until all these things happen.'),
  ('357ea68d-f25e-5992-a269-d1bebf7dfd2f', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 31, 31, 'Heaven and earth will pass away, but my words will not pass away.'),
  ('b5c48a6e-4f95-5844-ad93-c15526b46044', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 32, 32, 'But of that day or that hour no one knows, not even the angels in heaven, nor the Son, but only the Father.'),
  ('5d8304ed-2c46-513d-ab99-328ef600b55b', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 33, 33, 'Watch, keep alert, and pray; for you don''t know when the time is.'),
  ('77ecb354-9675-59eb-a4e0-280486ffd3a3', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 34, 34, '"It is like a man, traveling to another country, having left his house, and given authority to his servants, and to each one his work, and also commanded the doorkeeper to keep watch.'),
  ('3f8b4653-1635-5049-aa6d-177548aa9395', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 35, 35, 'Watch therefore, for you don''t know when the lord of the house is coming, whether at evening, or at midnight, or when the rooster crows, or in the morning;'),
  ('86390801-4110-5fe7-afd0-9787f5e163c3', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 36, 36, 'lest coming suddenly he might find you sleeping.'),
  ('fca4afc2-e17c-5a7f-aa97-ac8766f9af03', 'c7c52f60-400c-5925-a93c-885861d800a9', NULL, 37, 37, 'What I tell you, I tell all: Watch."'),
  ('92348865-aee6-5a74-ab8c-8d7bc10025e0', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 1, 1, 'It was now two days before the feast of the Passover and the unleavened bread, and the chief priests and the scribes sought how they might seize him by deception, and kill him.'),
  ('c86a15eb-6034-518f-a8fd-362dfcf5b316', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 2, 2, 'For they said, "Not during the feast, because there might be a riot of the people."'),
  ('dcc771bc-d753-5166-a1c3-7f69fbaf7038', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 3, 3, 'While he was at Bethany, in the house of Simon the leper, as he sat at the table, a woman came having an alabaster jar of ointment of pure nard--very costly. She broke the jar, and poured it over his head.'),
  ('a77c2945-43a8-55ea-a7f6-570f0571bcc7', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 4, 4, 'But there were some who were indignant among themselves, saying, "Why has this ointment been wasted?'),
  ('d44bb38c-7037-5523-a051-061c408897f3', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 5, 5, 'For this might have been sold for more than three hundred denarii, and given to the poor." They grumbled against her.'),
  ('a65c0e5a-600f-5c10-af84-5c99ca4efb76', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 6, 6, 'But Jesus said, "Leave her alone. Why do you trouble her? She has done a good work for me.'),
  ('b391cbee-3320-51d6-ab9e-37d7f2f6a931', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 7, 7, 'For you always have the poor with you, and whenever you want to, you can do them good; but you will not always have me.'),
  ('aa6d3183-ed9d-5160-ad1f-580517f930d4', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 8, 8, 'She has done what she could. She has anointed my body beforehand for the burying.'),
  ('cdbbddd2-97fc-53ee-aae1-3666cca6ce06', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 9, 9, 'Most certainly I tell you, wherever this Good News may be preached throughout the whole world, that which this woman has done will also be spoken of for a memorial of her."'),
  ('58594bd2-7d83-5a93-a57c-e081c9be894a', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 10, 10, 'Judas Iscariot, who was one of the twelve, went away to the chief priests, that he might deliver him to them.'),
  ('35cfcbe4-25fc-5945-ae3c-beeec0e90f88', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 11, 11, 'They, when they heard it, were glad, and promised to give him money. He sought how he might conveniently deliver him.'),
  ('e6b8ef76-caef-504b-a3a5-b98e12b8ea89', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 12, 12, 'On the first day of unleavened bread, when they sacrificed the Passover, his disciples asked him, "Where do you want us to go and prepare that you may eat the Passover?"'),
  ('7f0ad1a6-cc94-5238-a721-0477899340a3', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 13, 13, 'He sent two of his disciples, and said to them, "Go into the city, and there you will meet a man carrying a pitcher of water. Follow him,'),
  ('6dd750e9-9b16-5617-ad4f-8dd76ed5cc79', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 14, 14, 'and wherever he enters in, tell the master of the house, ''The Teacher says, "Where is the guest room, where I may eat the Passover with my disciples?"'''),
  ('971c11e3-0511-5741-a917-10130ebba264', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 15, 15, 'He will himself show you a large upper room furnished and ready. Get ready for us there."'),
  ('d7d4a50e-d639-55c8-a6c5-a1c02c5c13a5', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 16, 16, 'His disciples went out, and came into the city, and found things as he had said to them, and they prepared the Passover.'),
  ('acad150b-a2b1-5105-a970-c38180e3de32', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 17, 17, 'When it was evening he came with the twelve.'),
  ('6a86b30d-5eef-5ada-a2f8-5dec55168a1d', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 18, 18, 'As they sat and were eating, Jesus said, "Most certainly I tell you, one of you will betray me--he who eats with me."'),
  ('7850e114-1a9c-53c7-aa48-4e7d3a9ea544', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 19, 19, 'They began to be sorrowful, and to ask him one by one, "Surely not I?" And another said, "Surely not I?"'),
  ('e59e8590-d96c-5ee8-a03d-4de6184d457b', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 20, 20, 'He answered them, "It is one of the twelve, he who dips with me in the dish.'),
  ('f11624a7-930d-580f-a87a-8672703939cf', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 21, 21, 'For the Son of Man goes, even as it is written about him, but woe to that man by whom the Son of Man is betrayed! It would be better for that man if he had not been born."'),
  ('3aeed81b-d8a8-54a8-aec5-82cd31d5ca87', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 22, 22, 'As they were eating, Jesus took bread, and when he had blessed, he broke it, and gave to them, and said, "Take, eat. This is my body."'),
  ('2c139621-538a-5a90-a053-7040b42ef854', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 23, 23, 'He took the cup, and when he had given thanks, he gave to them. They all drank of it.'),
  ('926d0102-71b4-5487-a742-d187efe688c8', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 24, 24, 'He said to them, "This is my blood of the new covenant, which is poured out for many.'),
  ('b1e6630e-ced9-51fa-aa93-85c023581f2c', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 25, 25, 'Most certainly I tell you, I will no more drink of the fruit of the vine, until that day when I drink it anew in the Kingdom of God."'),
  ('331933dd-f9ac-56a5-a497-d0e810d43c4c', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 26, 26, 'When they had sung a hymn, they went out to the Mount of Olives.'),
  ('a4ada054-84db-55a4-a50f-0563792b6659', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 27, 27, 'Jesus said to them, "All of you will be made to stumble because of me tonight, for it is written, ''I will strike the shepherd, and the sheep will be scattered.'''),
  ('77364366-9a5b-5bac-a20c-ae02666d408b', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 28, 28, 'However, after I am raised up, I will go before you into Galilee."'),
  ('cc72217b-f9e2-5f40-a371-761c66f1f664', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 29, 29, 'But Peter said to him, "Although all will be offended, yet I will not."'),
  ('552a6b07-5756-5b75-a2fe-30629bf28ced', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 30, 30, 'Jesus said to him, "Most certainly I tell you, that you today, even this night, before the rooster crows twice, you will deny me three times."'),
  ('6e657c32-4d25-5ad7-aafa-918e9a24554f', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 31, 31, 'But he spoke all the more, "If I must die with you, I will not deny you." They all said the same thing.'),
  ('9b9cf743-f19e-5efe-a13b-ec8b65442755', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 32, 32, 'They came to a place which was named Gethsemane. He said to his disciples, "Sit here, while I pray."'),
  ('6416b642-3fff-5a21-ac32-6f118814777f', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 33, 33, 'He took with him Peter, James, and John, and began to be greatly troubled and distressed.'),
  ('c319eddd-b276-582c-a0fb-d8b9f02f6081', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 34, 34, 'He said to them, "My soul is exceedingly sorrowful, even to death. Stay here, and watch."'),
  ('0614b47a-fcbd-54a2-a353-3b6079200b00', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 35, 35, 'He went forward a little, and fell on the ground, and prayed that, if it were possible, the hour might pass away from him.'),
  ('d9f932fc-f711-551b-a866-c28b8e6662a0', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 36, 36, 'He said, "Abba, Father, all things are possible to you. Please remove this cup from me. However, not what I desire, but what you desire."'),
  ('af48cc92-235b-5dbe-abc4-8e31a6b4bfb7', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 37, 37, 'He came and found them sleeping, and said to Peter, "Simon, are you sleeping? Couldn''t you watch one hour?'),
  ('9e9abf6f-08cb-57a9-acb9-deeb4cb590bc', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 38, 38, 'Watch and pray, that you may not enter into temptation. The spirit indeed is willing, but the flesh is weak."'),
  ('25469b9a-24b6-5302-ae0d-f7384150004b', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 39, 39, 'Again he went away, and prayed, saying the same words.'),
  ('937d4068-8c8a-5965-aefd-9841d55cf294', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 40, 40, 'Again he returned, and found them sleeping, for their eyes were very heavy, and they didn''t know what to answer him.'),
  ('a5c594d1-38cf-59f2-a48c-3bb74e9ef724', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 41, 41, 'He came the third time, and said to them, "Sleep on now, and take your rest. It is enough. The hour has come. Behold, the Son of Man is betrayed into the hands of sinners.'),
  ('19719b24-9271-5432-a8ac-6d00a9ed28e2', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 42, 42, 'Arise, let us be going. Behold, he who betrays me is at hand."'),
  ('b750ac09-856f-57b7-aab8-424b8d634452', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 43, 43, 'Immediately, while he was still speaking, Judas, one of the twelve, came--and with him a multitude with swords and clubs, from the chief priests, the scribes, and the elders.'),
  ('3288cf12-7877-576c-a14c-b7cd7eec7cc2', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 44, 44, 'Now he who betrayed him had given them a sign, saying, "Whoever I will kiss, that is he. Seize him, and lead him away safely."'),
  ('a9cf773e-0e12-52c5-a287-858775d22343', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 45, 45, 'When he had come, immediately he came to him, and said, "Rabbi! Rabbi!" and kissed him.'),
  ('783452d7-123b-54fd-a0ee-3f440b4b804f', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 46, 46, 'They laid their hands on him, and seized him.'),
  ('1ea7aeda-3a6a-522d-a3ba-d8768df724ae', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 47, 47, 'But a certain one of those who stood by drew his sword, and struck the servant of the high priest, and cut off his ear.'),
  ('78693abb-705c-5ac5-a290-9931fa5e9516', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 48, 48, 'Jesus answered them, "Have you come out, as against a robber, with swords and clubs to seize me?'),
  ('68ef349e-6851-5d63-a3cb-033390e85adf', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 49, 49, 'I was daily with you in the temple teaching, and you didn''t arrest me. But this is so that the Scriptures might be fulfilled."'),
  ('cd9ec5e3-5444-5d2b-a803-1168b4dedb40', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 50, 50, 'They all left him, and fled.'),
  ('967aae47-1b2f-5007-a6ed-c68056202ca8', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 51, 51, 'A certain young man followed him, having a linen cloth thrown around himself, over his naked body. The young men grabbed him,'),
  ('84059ee5-acb4-5fff-a07d-be413b594e6e', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 52, 52, 'but he left the linen cloth, and fled from them naked.'),
  ('0b468074-7509-534b-a5a6-59d17b1bfad1', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 53, 53, 'They led Jesus away to the high priest. All the chief priests, the elders, and the scribes came together with him.'),
  ('ad76caee-b9d3-5cb0-acf9-ff406bb57c30', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 54, 54, 'Peter had followed him from a distance, until he came into the court of the high priest. He was sitting with the officers, and warming himself in the light of the fire.'),
  ('db87f5ef-f7ed-5e71-abdb-186ac1520d4f', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 55, 55, 'Now the chief priests and the whole council sought witnesses against Jesus to put him to death, and found none.'),
  ('bd93fcc9-609c-5bd6-a100-231ac76bf2bf', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 56, 56, 'For many gave false testimony against him, and their testimony didn''t agree with each other.'),
  ('1cfaa5ae-c136-599c-acb3-af2c5002a7cb', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 57, 57, 'Some stood up, and gave false testimony against him, saying,'),
  ('c71012fd-d84a-5f18-a1d7-f60a64c3dbdd', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 58, 58, '"We heard him say, ''I will destroy this temple that is made with hands, and in three days I will build another made without hands.''"'),
  ('8e2a0f46-a321-583b-a584-0fdc9aed988a', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 59, 59, 'Even so, their testimony did not agree.'),
  ('3a3aaf3d-8b53-5404-a872-34b5cbefcac3', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 60, 60, 'The high priest stood up in the midst, and asked Jesus, "Have you no answer? What is it which these testify against you?"'),
  ('3a331450-ac42-556e-a794-77a63cb71cce', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 61, 61, 'But he stayed quiet, and answered nothing. Again the high priest asked him, "Are you the Christ, the Son of the Blessed?"'),
  ('06926ddc-c0fb-5ec7-aa65-abfbd6e486d7', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 62, 62, 'Jesus said, "I am. You will see the Son of Man sitting at the right hand of Power, and coming with the clouds of the sky."'),
  ('c0e68ee3-cdbe-5b40-ac78-ddb0442e96f4', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 63, 63, 'The high priest tore his clothes, and said, "What further need have we of witnesses?'),
  ('d15a7e30-f807-538d-a744-fe27f0357ad4', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 64, 64, 'You have heard the blasphemy! What do you think?" They all condemned him to be worthy of death.'),
  ('16c79296-3ed2-5ff9-acca-105f8381c3f9', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 65, 65, 'Some began to spit on him, and to cover his face, and to beat him with fists, and to tell him, "Prophesy!" The officers struck him with the palms of their hands.'),
  ('8dcffabb-f2c7-5421-af7f-07475fc6341d', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 66, 66, 'As Peter was in the courtyard below, one of the maids of the high priest came,'),
  ('8b06651d-5314-59e9-a128-0a0b46de503e', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 67, 67, 'and seeing Peter warming himself, she looked at him, and said, "You were also with the Nazarene, Jesus!"'),
  ('7b2e9260-be23-5fd5-aa89-951e7e0c1128', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 68, 68, 'But he denied it, saying, "I neither know, nor understand what you are saying." He went out on the porch, and the rooster crowed.'),
  ('5ca5f154-a5d8-548c-a6d5-b7beeaab15a8', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 69, 69, 'The maid saw him, and began again to tell those who stood by, "This is one of them."'),
  ('97768655-e04b-5d13-a8cf-20919e246ad1', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 70, 70, 'But he again denied it. After a little while again those who stood by said to Peter, "You truly are one of them, for you are a Galilean, and your speech shows it."'),
  ('9fe5917c-caa8-5263-a585-8a1860a3f1e1', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 71, 71, 'But he began to curse, and to swear, "I don''t know this man of whom you speak!"'),
  ('8913e9b2-cb83-5a09-ae5c-03d5ca14a134', '1e6a9a74-4a09-56cd-acde-4b702ad6ba9e', NULL, 72, 72, 'The rooster crowed the second time. Peter remembered the word, how that Jesus said to him, "Before the rooster crows twice, you will deny me three times." When he thought about that, he wept.'),
  ('b08635dd-b144-5632-a9a7-9f9504e03d01', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 1, 1, 'Immediately in the morning the chief priests, with the elders and scribes, and the whole council, held a consultation, and bound Jesus, and carried him away, and delivered him up to Pilate.'),
  ('1282a54c-a418-54e5-aa5c-0fd9a8b21d89', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 2, 2, 'Pilate asked him, "Are you the King of the Jews?" He answered, "So you say."'),
  ('5af6aaaf-399c-53c8-a77b-0789e90b78f1', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 3, 3, 'The chief priests accused him of many things.'),
  ('c4fdd0fb-9bd0-5648-a28e-f7f7256fceb0', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 4, 4, 'Pilate again asked him, "Have you no answer? See how many things they testify against you!"'),
  ('c3b67798-826d-500c-aa18-e115c91e024a', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 5, 5, 'But Jesus made no further answer, so that Pilate marveled.'),
  ('8785a8ca-ee61-5bfe-a7ba-02315a55ad92', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 6, 6, 'Now at the feast he used to release to them one prisoner, whom they asked of him.'),
  ('a81506be-b299-52c9-a1d1-b8fcdc738367', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 7, 7, 'There was one called Barabbas, bound with those who had made insurrection, men who in the insurrection had committed murder.'),
  ('dacfc14c-0dd2-5d6c-aa5b-33ca89f7aa23', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 8, 8, 'The multitude, crying aloud, began to ask him to do as he always did for them.'),
  ('c05b09e9-aeee-5043-ab14-5627e81df8d4', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 9, 9, 'Pilate answered them, saying, "Do you want me to release to you the King of the Jews?"'),
  ('dcb08bca-a07d-5eb1-af28-1e1b8ef924b0', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 10, 10, 'For he perceived that for envy the chief priests had delivered him up.'),
  ('2fdab308-ca5e-574b-a76e-3b70908ad794', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 11, 11, 'But the chief priests stirred up the multitude, that he should release Barabbas to them instead.'),
  ('2066bb5a-ed15-5e41-a117-e2cdcfde70fd', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 12, 12, 'Pilate again asked them, "What then should I do to him whom you call the King of the Jews?"'),
  ('7da86393-2859-5d6b-a71e-192bbe5bb360', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 13, 13, 'They cried out again, "Crucify him!"'),
  ('7d20493d-9fa8-550a-a3d9-6a6bea4d0a8a', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 14, 14, 'Pilate said to them, "Why, what evil has he done?" But they cried out exceedingly, "Crucify him!"'),
  ('c5222125-0376-5cfc-a2b6-75d4dc848fa2', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 15, 15, 'Pilate, wishing to please the multitude, released Barabbas to them, and handed over Jesus, when he had flogged him, to be crucified.'),
  ('af56d629-eba2-5ebb-a69f-9aff67f77bd1', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 16, 16, 'The soldiers led him away within the court, which is the Praetorium; and they called together the whole cohort.'),
  ('54cd19d8-754a-59b5-a5e4-87d98fa9ced6', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 17, 17, 'They clothed him with purple, and weaving a crown of thorns, they put it on him.'),
  ('2438cdac-9517-5651-a1a3-67af0de4b3be', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 18, 18, 'They began to salute him, "Hail, King of the Jews!"'),
  ('4969b105-1e3e-508b-a1ee-a6d1c7be99da', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 19, 19, 'They struck his head with a reed, and spat on him, and bowing their knees, did homage to him.'),
  ('01ee291d-e198-55d4-a24f-fa6af8acd349', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 20, 20, 'When they had mocked him, they took the purple off of him, and put his own garments on him. They led him out to crucify him.'),
  ('4ba611e6-4edf-555f-a924-934d3b151446', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 21, 21, 'They compelled one passing by, coming from the country, Simon of Cyrene, the father of Alexander and Rufus, to go with them, that he might bear his cross.'),
  ('28de8e4e-d91d-500a-a1d0-662be72dc0b0', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 22, 22, 'They brought him to the place called Golgotha, which is, being interpreted, "The place of a skull."'),
  ('2c59cb87-b531-5862-a534-9d28206c99e2', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 23, 23, 'They offered him wine mixed with myrrh to drink, but he didn''t take it.'),
  ('dbdba857-6e07-560d-a378-c8d7016934c5', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 24, 24, 'Crucifying him, they parted his garments among them, casting lots on them, what each should take.'),
  ('38299260-6c68-55d5-ad83-c7283eb3c039', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 25, 25, 'It was the third hour, and they crucified him.'),
  ('5618dc87-24b8-5053-a28f-c65dd27a761b', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 26, 26, 'The superscription of his accusation was written over him, "THE KING OF THE JEWS."'),
  ('56f36ee3-3fbd-5df8-ae39-bb5f41d1f7cb', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 27, 27, 'With him they crucified two robbers; one on his right hand, and one on his left.'),
  ('d403e2e1-574f-58e9-a6a8-3a4eac7a49c1', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 28, 28, 'The Scripture was fulfilled, which says, "He was numbered with transgressors."'),
  ('8651c8c4-5448-50f2-a4ca-14b7b5178b9e', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 29, 29, 'Those who passed by blasphemed him, wagging their heads, and saying, "Ha! You who destroy the temple, and build it in three days,'),
  ('d4d26e59-3c26-564c-ae74-b2b483cbfb11', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 30, 30, 'save yourself, and come down from the cross!"'),
  ('230a5ea1-a9df-5c24-a49f-f214ae38d006', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 31, 31, 'Likewise, also the chief priests mocking among themselves with the scribes said, "He saved others. He can''t save himself.'),
  ('08a1a0b9-6d8e-58e0-aa21-05a1870d2dc5', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 32, 32, 'Let the Christ, the King of Israel, now come down from the cross, that we may see and believe him." Those who were crucified with him insulted him.'),
  ('3960dd4d-c29f-55d6-a1c9-5f4d7600233e', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 33, 33, 'When the sixth hour had come, there was darkness over the whole land until the ninth hour.'),
  ('7eddc5b4-5eb7-51ef-a4bd-df90e23f85f4', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 34, 34, 'At the ninth hour Jesus cried with a loud voice, saying, "Eloi, Eloi, lama sabachthani?" which is, being interpreted, "My God, my God, why have you forsaken me?"')
